import type { RoomTemplate } from './types'

function createCombatArena(
  id: string,
  name: string,
  biomeId: RoomTemplate['biomeId'],
  size: RoomTemplate['size'],
  occluders: RoomTemplate['occluders'],
): RoomTemplate {
  const halfX = size.x / 2
  const halfZ = size.z / 2
  const positions = [
    [-0.32, -0.34],
    [0, -0.38],
    [0.34, -0.32],
    [-0.38, 0],
    [0.38, 0],
    [-0.32, 0.34],
    [0, 0.38],
    [0.34, 0.32],
    [-0.08, -0.08],
    [0.16, 0.12],
    [-0.42, 0.2],
    [0.42, -0.2],
  ] as const
  return {
    id,
    name,
    kind: 'combat',
    biomeId,
    size,
    sockets: [
      { id: 'south', position: { x: 0, z: halfZ }, direction: 'south' },
      { id: 'north', position: { x: 0, z: -halfZ }, direction: 'north' },
    ],
    spawns: [
      { id: 'player', role: 'player', position: { x: 0, z: halfZ - 2.5 } },
      ...positions.map(([x, z], index) => ({
        id: `enemy-${index + 1}`,
        role: 'enemy' as const,
        position: { x: x * size.x, z: z * size.z },
        archetypeId: 'grave-husk' as const,
        minCombatTier: (index < 6 ? 1 : index < 8 ? 2 : 3) as 1 | 2 | 3,
      })),
      { id: 'reward', role: 'reward', position: { x: 0, z: -halfZ + 1.5 } },
    ],
    occluders,
    waypoints: [
      { id: 'south', position: { x: 0, z: halfZ - 3 }, neighbors: ['center'] },
      { id: 'west', position: { x: -halfX + 3, z: 0 }, neighbors: ['center'] },
      {
        id: 'center',
        position: { x: 0, z: 0 },
        neighbors: ['south', 'west', 'east', 'north'],
      },
      { id: 'east', position: { x: halfX - 3, z: 0 }, neighbors: ['center'] },
      { id: 'north', position: { x: 0, z: -halfZ + 3 }, neighbors: ['center'] },
    ],
  }
}

