export function getRoomTemplate(id: string): RoomTemplate {
  const template = ROOM_TEMPLATES.find((room) => room.id === id)
  if (template === undefined) {
    throw new RangeError(`Unknown room template: ${id}`)
  }
  return template
}

/**
 * Escape pacing: sectors physically grow as the run deepens.
 *
 * The objective is reaching the exit, so distance is the difficulty dial —
 * every chamber adds floor between the player and the way out while enemy
 * counts stay authored, which reads as rising pressure rather than a bigger
 * kill list. Capped before pathing distances outgrow the camera's framing.
 */
export function getRoomScale(chamber: number): number {
  if (!Number.isFinite(chamber) || chamber <= 1) return 1
  return Math.min(1.55, 1 + (chamber - 1) * 0.06)
}

/** Uniformly scales a room's footprint and everything positioned inside it. */
export function scaleRoomTemplate(
  template: RoomTemplate,
  scale: number,
): RoomTemplate {
  if (!Number.isFinite(scale) || Math.abs(scale - 1) < 0.001) return template
  const scaleVec = (point: { x: number; z: number }) => ({
    x: point.x * scale,
    z: point.z * scale,
  })
  return {
    ...template,
    size: scaleVec(template.size),
    sockets: template.sockets.map((socket) => ({
      ...socket,
      position: scaleVec(socket.position),
    })),
    spawns: template.spawns.map((spawn) => ({
      ...spawn,
      position: scaleVec(spawn.position),
    })),
    occluders: template.occluders.map((occluder) => ({
      ...occluder,
      center: scaleVec(occluder.center),
      // Cover scales with the room so sightline play keeps its proportions;
      // height stays authored because the camera pitch never changes.
      halfExtents: scaleVec(occluder.halfExtents),
    })),
    waypoints: template.waypoints.map((waypoint) => ({
      ...waypoint,
      position: scaleVec(waypoint.position),
    })),
  }
}
