import type { EffectSpawn } from '../../runtime/gameStore'

/**
 * Imperative spawn bus for visual effects.
 *
 * Effects used to live in the zustand store for their whole lifetime: one
 * React component each, a per-frame material traverse, and a store write on
 * every expiry. That model cannot carry particles — it would mean one React
 * component per particle. Here a spawn is an *event* that is drained once by
 * the renderer, and lifetime belongs to the particle engine.
 *
 * DETERMINISM: nothing in this module may touch the seeded run RNG. Runs are
 * reproducible from a seed and the e2e suite pins a full ten-chamber route, so
 * VFX randomness is deliberately kept on a separate, non-reproducible stream
 * (see vfxRandom). Visual variety must never feed back into simulation.
 */

/**
 * Hard ceiling on queued-but-undrained spawns. Reached only if the renderer
 * stalls; dropping the oldest is correct because a stale VFX is worthless.
 */
const MAX_PENDING = 128

const pending: EffectSpawn[] = []
let droppedCount = 0
let drainedCount = 0

export function enqueueVfx(effect: EffectSpawn): void {
  if (pending.length >= MAX_PENDING) {
    pending.shift()
    droppedCount += 1
  }
  pending.push(effect)
}

/**
 * Shared empty result. `drainVfx` runs every frame and is empty on most of
 * them, so the idle path must not allocate.
 */
const NO_VFX: readonly EffectSpawn[] = Object.freeze([])

/**
 * Hands over everything queued since the last call and empties the queue.
 * A non-empty result is a fresh copy the caller may hold across frames; the
 * empty result is shared and frozen, so it must not be mutated.
 */
export function drainVfx(): readonly EffectSpawn[] {
  if (pending.length === 0) return NO_VFX
  const drained = pending.slice()
  pending.length = 0
  drainedCount += drained.length
  return drained
}

export function pendingVfxCount(): number {
  return pending.length
}

export function droppedVfxCount(): number {
  return droppedCount
}

export function drainedVfxCount(): number {
  return drainedCount
}

export function resetVfxQueue(): void {
  pending.length = 0
  droppedCount = 0
  drainedCount = 0
}

/**
 * Randomness for presentation only.
 *
 * Intentionally NOT seeded and intentionally not `createRandomStream` from the
 * game layer. Two players on the same seed must get the same run; they do not
 * need the same spark to fly the same way, and wiring VFX into the run streams
 * would make particle count a determinism input.
 */
export function vfxRandom(): number {
  return Math.random()
}

export function vfxRandomRange(minimum: number, maximum: number): number {
  return minimum + vfxRandom() * (maximum - minimum)
}
