import type { ChamberLevel, DifficultyRank } from './types'

export interface ChamberScaling {
  readonly healthMultiplier: number
  readonly damageMultiplier: number
  readonly moveSpeedMultiplier: number
  readonly windupMultiplier: number
  readonly recoveryMultiplier: number
  readonly projectileSpeedMultiplier: number
}

export interface DifficultyRankDefinition extends ChamberScaling {
  readonly rank: DifficultyRank
  readonly label: string
  readonly payoutMultiplier: number
  readonly attackTokenBonus: number
  readonly rangedTokenBonus: number
  readonly veilBreakAfterMs: number
  readonly veilRearmHiddenMs: number
  readonly wardenBreakAfterMs: number
  readonly wardenRearmHiddenMs: number
  readonly queenBreakAfterMs: number
}

export interface CombatScaling extends ChamberScaling {
  readonly chamber: number
  readonly difficulty: DifficultyRank
  /** Blind thralls receive full chamber growth but only 35% of rank HP growth. */
  readonly weakEnemyHealthMultiplier: number
}

