export const DIFFICULTY_RANK_DEFINITIONS = DIFFICULTY_RANKS

export function isDifficultyRank(value: unknown): value is DifficultyRank {
  return (
    typeof value === 'number' &&
    Number.isInteger(value) &&
    value >= 1 &&
    value <= 5
  )
}

export function isChamberLevel(value: unknown): value is ChamberLevel {
  return (
    typeof value === 'number' &&
    Number.isInteger(value) &&
    value >= 1 &&
    value <= 10
  )
}

export function getDifficultyRankDefinition(
  difficulty: DifficultyRank,
): DifficultyRankDefinition {
  return DIFFICULTY_RANKS[difficulty]
}

/**
 * Full containment label, e.g. `격리 등급 III`.
 * call sites used to retype the numeral array instead.
 */
export function getDifficultyLabel(difficulty: DifficultyRank): string {
  return DIFFICULTY_RANKS[difficulty].label
}

export function getChamberScaling(chamber: number): ChamberScaling {
  if (!Number.isSafeInteger(chamber) || chamber < 1) {
    throw new RangeError(`Invalid combat chamber: ${chamber}`)
  }
  const step = chamber - 1
  return Object.freeze({
    healthMultiplier: 1 + 0.06 * step,
    damageMultiplier: 1 + 0.035 * step,
    // Endless damage/health may keep climbing, but uncapped locomotion and
    // projectiles eventually become unreadable rather than meaningfully hard.
    moveSpeedMultiplier: Math.min(1.35, 1 + 0.018 * step),
    windupMultiplier: Math.max(0.74, 1 - 0.03 * step),
    recoveryMultiplier: Math.max(0.72, 1 - 0.035 * step),
    projectileSpeedMultiplier: Math.min(1.5, 1 + 0.025 * step),
  })
}

export function getCombatScaling(
  chamber: number,
  difficulty: DifficultyRank = 1,
): CombatScaling {
  const chamberScaling = getChamberScaling(chamber)
  const rankScaling = getDifficultyRankDefinition(difficulty)

  return Object.freeze({
    chamber,
    difficulty,
    healthMultiplier:
      chamberScaling.healthMultiplier * rankScaling.healthMultiplier,
    weakEnemyHealthMultiplier:
      chamberScaling.healthMultiplier *
      (1 + (rankScaling.healthMultiplier - 1) * 0.35),
    damageMultiplier:
      chamberScaling.damageMultiplier * rankScaling.damageMultiplier,
    moveSpeedMultiplier:
      chamberScaling.moveSpeedMultiplier * rankScaling.moveSpeedMultiplier,
    windupMultiplier:
      chamberScaling.windupMultiplier * rankScaling.windupMultiplier,
    recoveryMultiplier:
      chamberScaling.recoveryMultiplier * rankScaling.recoveryMultiplier,
    projectileSpeedMultiplier:
      chamberScaling.projectileSpeedMultiplier *
      rankScaling.projectileSpeedMultiplier,
  })
}
