import type {
  MetaProgression,
  PermanentStatDefinition,
  PermanentStatId,
  PermanentStatLevel,
  PermanentStatLevels,
  PermanentStatProfile,
} from './types'
import { BASE_PLAYER_STATS, PLAYER_STAT_CAPS } from './upgrades'

export const PERMANENT_STAT_COSTS = [20, 35, 55, 85, 125] as const

export const PERMANENT_STAT_DEFINITIONS = [
  {
    id: 'vitality',
    name: '생명유지 보강',
    description: '레벨마다 기본 최대 내구도와 상한이 3 증가합니다.',
    maxLevel: 5,
    costs: PERMANENT_STAT_COSTS,
  },
  {
    id: 'power',
    name: '무장 출력 보정',
    description: '레벨마다 기본 공격력과 상한이 5% 증가합니다.',
    maxLevel: 5,
    costs: PERMANENT_STAT_COSTS,
  },
  {
    id: 'mobility',
    name: '구동계 보정',
    description: '레벨마다 기본 이동 속도와 상한이 2% 증가합니다.',
    maxLevel: 5,
    costs: PERMANENT_STAT_COSTS,
  },
  {
    id: 'gaze',
    name: '광학 센서 보정',
    description: '레벨마다 관측 거리 0.35와 관측 각도 4°가 증가합니다.',
    maxLevel: 5,
    costs: PERMANENT_STAT_COSTS,
  },
] as const satisfies readonly PermanentStatDefinition[]

export const EMPTY_PERMANENT_STAT_LEVELS: PermanentStatLevels = Object.freeze({
  vitality: 0,
  power: 0,
  mobility: 0,
  gaze: 0,
})

const definitionsById = new Map<PermanentStatId, PermanentStatDefinition>(
  PERMANENT_STAT_DEFINITIONS.map((definition) => [definition.id, definition]),
)

export function isPermanentStatId(value: unknown): value is PermanentStatId {
  return (
    typeof value === 'string' && definitionsById.has(value as PermanentStatId)
  )
}

export function isPermanentStatLevel(
  value: unknown,
): value is PermanentStatLevel {
  return (
    typeof value === 'number' &&
    Number.isInteger(value) &&
    value >= 0 &&
    value <= 5
  )
}

export function readPermanentStatLevels(
  value: unknown,
): PermanentStatLevels | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return null
  }
  const record = value as Record<string, unknown>
  if (
    !isPermanentStatLevel(record.vitality) ||
    !isPermanentStatLevel(record.power) ||
    !isPermanentStatLevel(record.mobility) ||
    !isPermanentStatLevel(record.gaze)
  ) {
    return null
  }
  return {
    vitality: record.vitality,
    power: record.power,
    mobility: record.mobility,
    gaze: record.gaze,
  }
}

export function getPermanentStatDefinition(
  id: PermanentStatId,
): PermanentStatDefinition {
  const definition = definitionsById.get(id)
  if (definition === undefined) {
    throw new RangeError(`Unknown permanent stat: ${id}`)
  }
  return definition
}

export function getPermanentStatPurchaseCost(
  id: PermanentStatId,
  currentLevel: PermanentStatLevel,
): number | null {
  if (currentLevel >= 5) return null
  return getPermanentStatDefinition(id).costs[currentLevel as 0 | 1 | 2 | 3 | 4]
}

export function derivePermanentStatProfile(
  levels: PermanentStatLevels,
): PermanentStatProfile {
  // Vitality is a legacy save field. Health upgrades are deliberately retired:
  // old vitality investment remains converted into gaze training so existing
  // saves keep the build value granted by the earlier progression redesign.
  const effectiveGazeLevel = Math.min(5, levels.gaze + levels.vitality)
  const powerMultiplier = 1 + levels.power * 0.05
  const mobilityMultiplier = 1 + levels.mobility * 0.02
  const visionRangeAdd = effectiveGazeLevel * 0.35
  const visionFovDegAdd = effectiveGazeLevel * 4

  return {
    stats: {
      ...BASE_PLAYER_STATS,
      attackDamage: BASE_PLAYER_STATS.attackDamage * powerMultiplier,
      moveSpeed: BASE_PLAYER_STATS.moveSpeed * mobilityMultiplier,
      visionRange: BASE_PLAYER_STATS.visionRange + visionRangeAdd,
      visionFovDeg: BASE_PLAYER_STATS.visionFovDeg + visionFovDegAdd,
    },
    caps: {
      ...PLAYER_STAT_CAPS,
      attackDamage: PLAYER_STAT_CAPS.attackDamage * powerMultiplier,
      moveSpeed: PLAYER_STAT_CAPS.moveSpeed * mobilityMultiplier,
      visionRange: PLAYER_STAT_CAPS.visionRange + visionRangeAdd,
      visionFovDeg: PLAYER_STAT_CAPS.visionFovDeg + visionFovDegAdd,
    },
  }
}

export type PermanentStatPurchaseFailure =
  'unknown-stat' | 'max-level' | 'seal-locked' | 'insufficient-funds'

export type PermanentStatPurchaseResult =
  | { readonly ok: true; readonly meta: MetaProgression; readonly cost: number }
  | {
      readonly ok: false
      readonly meta: MetaProgression
      readonly reason: PermanentStatPurchaseFailure
    }

export function purchasePermanentStatLevel(
  meta: MetaProgression,
  statId: string,
): PermanentStatPurchaseResult {
  if (!isPermanentStatId(statId)) {
    return { ok: false, meta, reason: 'unknown-stat' }
  }
  const currentLevel = meta.permanentStatLevels[statId]
  const cost = getPermanentStatPurchaseCost(statId, currentLevel)
  if (cost === null) return { ok: false, meta, reason: 'max-level' }

  const nextLevel = (currentLevel + 1) as PermanentStatLevel
  if (meta.currency < cost) {
    return { ok: false, meta, reason: 'insufficient-funds' }
  }

  return {
    ok: true,
    cost,
    meta: {
      ...meta,
      currency: meta.currency - cost,
      permanentStatLevels: {
        ...meta.permanentStatLevels,
        [statId]: nextLevel,
      },
    },
  }
}
