import { isDailyDateKey } from './daily'
import { isDifficultyRank } from './difficulty'
import {
  DEFAULT_LOADOUT,
  ITEM_IDS,
  STARTER_ITEM_IDS,
  canonicalizeOwnedItemIds,
  getItem,
  isItemId,
} from './items'
import {
  EMPTY_PERMANENT_STAT_LEVELS,
  readPermanentStatLevels,
} from './permanentStats'
import { EMPTY_DIFFICULTY_PROGRESS } from './progression'
import { RANGED_WEAPON_IDS, isPassiveId, isRangedWeaponId } from './runBuild'
/** Legacy training vocabulary retained so shipped saves remain readable. */
const TRAINING_SCENARIO_IDS = [
  'basics',
  'gaze-rules',
  'combat-practice',
] as const satisfies readonly TrainingScenarioId[]
import type {
  BossArchetypeId,
  CompletedDifficultyRank,
  DailyRecord,
  DifficultyChamberProgress,
  EquipmentLoadout,
  GameSettings,
  ItemId,
  MetaProgression,
  MetaProgressionV1,
  MetaProgressionV2,
  MetaProgressionV3,
  MetaProgressionV4,
  MetaProgressionV5,
  MetaProgressionV6,
  MotionPreference,
  SaveDataV1,
  SaveDataV2,
  SaveDataV3,
  SaveDataV4,
  SaveDataV5,
  SaveDataV6,
  SaveDataV7,
  SaveDataV8,
  SaveLoadResult,
  TrainingScenarioId,
  UpgradeId,
} from './types'
import { UPGRADE_IDS } from './upgrades'

const upgradeIds = new Set<string>(UPGRADE_IDS)
const bossIds = new Set<BossArchetypeId>([
  'grave-warden',
  'moonbriar-queen',
  'parallax-seraph',
  'null-crown',
])

function createDefaultV2Meta(): MetaProgressionV2 {
  return {
    runsStarted: 0,
    runsWon: 0,
    bestRoom: 0,
    unlockedUpgradeIds: [],
    currency: 0,
    ownedItemIds: [...STARTER_ITEM_IDS],
    loadout: { ...DEFAULT_LOADOUT },
  }
}

function upgradeV2Meta(meta: MetaProgressionV2): MetaProgressionV3 {
  return {
    ...meta,
    bestChamberByDifficulty: {
      ...EMPTY_DIFFICULTY_PROGRESS,
      1: Math.min(meta.bestRoom, 10),
    },
    highestDifficultyUnlocked: 1,
    highestDifficultyCleared: 0,
    lastSelectedDifficulty: 1,
  }
}

function upgradeV3Meta(meta: MetaProgressionV3): MetaProgressionV4 {
  return {
    ...meta,
    permanentStatLevels: { ...EMPTY_PERMANENT_STAT_LEVELS },
    completedTrainingScenarioIds: [],
    trainingPromptSeen: false,
  }
}

function upgradeV4Meta(meta: MetaProgressionV4): MetaProgressionV5 {
  return { ...meta, dailyRecords: [] }
}

function upgradeV5Meta(meta: MetaProgressionV5): MetaProgressionV6 {
  return {
    ...meta,
    bestScoreByDifficulty: { ...EMPTY_DIFFICULTY_PROGRESS },
    bossClears: { 'grave-warden': 0, 'moonbriar-queen': 0 },
    firstRunTutorialSeen: false,
  }
}

// Weapons are a baseline combat choice rather than meta-progression. Keeping
// the existing save field lets older profiles remain readable while this
// default backfills every shipped ranged weapon for new and returning players.
const DEFAULT_UNLOCKED_WEAPON_IDS = RANGED_WEAPON_IDS
const DEFAULT_UNLOCKED_PASSIVE_IDS = [
  'high-voltage-core',
  'overclock-governor',
  'heavy-frame',
  'magnetic-collector',
  // The optic field is the game's core rule, so its two shaping passives are
  // never gated behind a purchase.
  'precision-sight',
  'panoramic-sight',
] as const

function upgradeV6Meta(meta: MetaProgressionV6): MetaProgression {
  const convertedWeapons = new Set<string>(DEFAULT_UNLOCKED_WEAPON_IDS)
  const convertedPassives = new Set<string>(DEFAULT_UNLOCKED_PASSIVE_IDS)
  if (meta.ownedItemIds.includes('watcher-lens')) {
    convertedWeapons.add('rail-lance')
    convertedPassives.add('long-range-lens')
  }
  if (meta.unlockedUpgradeIds.includes('rapid-rune')) {
    convertedWeapons.add('arc-emitter')
    convertedPassives.add('phase-accelerator')
  }
  if (meta.unlockedUpgradeIds.includes('far-sight')) {
    convertedWeapons.add('orbit-drone')
    convertedPassives.add('penetration-algorithm')
  }
  return {
    ...meta,
    unlockedWeaponIds: [...convertedWeapons],
    unlockedPassiveIds: [...convertedPassives],
    starterRangedWeaponId: 'pulse-carbine',
  }
}

export function createDefaultMetaProgression(): MetaProgression {
  return upgradeV6Meta(
    upgradeV5Meta(
      upgradeV4Meta(upgradeV3Meta(upgradeV2Meta(createDefaultV2Meta()))),
    ),
  )
}

export function createDefaultSave(): SaveDataV8 {
  return {
    version: 8,
    settings: {
      masterVolume: 0.8,
      musicVolume: 0.7,
      sfxVolume: 0.8,
      cameraShake: true,
      motionPreference: 'auto',
    },
    meta: createDefaultMetaProgression(),
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function isVolume(value: unknown): value is number {
  return (
    typeof value === 'number' &&
    Number.isFinite(value) &&
    value >= 0 &&
    value <= 1
  )
}

function isNonNegativeInteger(value: unknown): value is number {
  return Number.isSafeInteger(value) && (value as number) >= 0
}

function isLegacyBestRoom(value: unknown): value is number {
  return isNonNegativeInteger(value) && value <= 5
}

function isLegacyRunBestRoom(value: unknown): value is number {
  return isNonNegativeInteger(value) && value <= 10
}

function isCurrentRunBestRoom(value: unknown): value is number {
  return isNonNegativeInteger(value)
}

function isDailyBestChamber(value: unknown): value is number {
  return isNonNegativeInteger(value) && value <= 10
}

type ChamberProgressValidator = (value: unknown) => value is number

function isCompletedDifficultyRank(
  value: unknown,
): value is CompletedDifficultyRank {
  return (
    typeof value === 'number' &&
    Number.isInteger(value) &&
    value >= 0 &&
    value <= 5
  )
}

function readUpgradeIds(value: unknown): UpgradeId[] | null {
  if (!Array.isArray(value) || value.length > 64) return null
  if (!value.every((id) => typeof id === 'string' && upgradeIds.has(id))) {
    return null
  }
  return [...new Set(value)] as UpgradeId[]
}

function readItemIds(value: unknown): ItemId[] | null {
  if (!Array.isArray(value) || value.length > 32 || !value.every(isItemId)) {
    return null
  }
  return canonicalizeOwnedItemIds(value)
}

const MOTION_PREFERENCES = [
  'auto',
  'full',
  'reduced',
] as const satisfies readonly MotionPreference[]

/** Absent is valid: saves written before the field existed must still load. */
function isMotionPreference(value: unknown): boolean {
  return (
    value === undefined ||
    MOTION_PREFERENCES.includes(value as (typeof MOTION_PREFERENCES)[number])
  )
}

function isGameSettings(value: unknown): value is GameSettings {
  return (
    isRecord(value) &&
    isVolume(value.masterVolume) &&
    isVolume(value.musicVolume) &&
    isVolume(value.sfxVolume) &&
    typeof value.cameraShake === 'boolean' &&
    isMotionPreference(value.motionPreference)
  )
}

function isMetaProgressionV1(value: unknown): value is MetaProgressionV1 {
  return (
    isRecord(value) &&
    isNonNegativeInteger(value.runsStarted) &&
    isNonNegativeInteger(value.runsWon) &&
    isLegacyBestRoom(value.bestRoom) &&
    readUpgradeIds(value.unlockedUpgradeIds) !== null
  )
}

function readValidLoadout(
  value: unknown,
  ownedItemIds: readonly ItemId[],
): EquipmentLoadout | null {
  if (!isRecord(value)) return null
  const { weapon, armor, charm } = value
  if (!isItemId(weapon) || !isItemId(armor)) return null
  if (charm !== null && !isItemId(charm)) return null
  if (
    !ownedItemIds.includes(weapon) ||
    !ownedItemIds.includes(armor) ||
    (charm !== null && !ownedItemIds.includes(charm))
  ) {
    return null
  }
  if (
    getItem(weapon).slot !== 'weapon' ||
    getItem(armor).slot !== 'armor' ||
    (charm !== null && getItem(charm).slot !== 'charm')
  ) {
    return null
  }
  return { weapon, armor, charm }
}

function isMetaProgressionV2(value: unknown): value is MetaProgressionV2 {
  if (
    !isRecord(value) ||
    !isMetaProgressionV1(value) ||
    !isNonNegativeInteger(value.currency)
  ) {
    return false
  }
  const owned = readItemIds(value.ownedItemIds)
  return (
    owned !== null &&
    STARTER_ITEM_IDS.every((id) => owned.includes(id)) &&
    readValidLoadout(value.loadout, owned) !== null
  )
}

function readDifficultyProgress(
  value: unknown,
  validateChamber: ChamberProgressValidator = isLegacyRunBestRoom,
): DifficultyChamberProgress | null {
  if (!isRecord(value)) return null
  const values = [value[1], value[2], value[3], value[4], value[5]]
  if (!values.every(validateChamber)) return null
  return {
    1: values[0] as number,
    2: values[1] as number,
    3: values[2] as number,
    4: values[3] as number,
    5: values[4] as number,
  }
}

function readScoreProgress(value: unknown): DifficultyChamberProgress | null {
  if (!isRecord(value)) return null
  const values = [value[1], value[2], value[3], value[4], value[5]]
  if (!values.every(isNonNegativeInteger)) return null
  return {
    1: values[0] as number,
    2: values[1] as number,
    3: values[2] as number,
    4: values[3] as number,
    5: values[4] as number,
  }
}

function isMetaProgressionV3(
  value: unknown,
  validateChamber: ChamberProgressValidator = isLegacyRunBestRoom,
): value is MetaProgressionV3 {
  if (
    !isRecord(value) ||
    !isNonNegativeInteger(value.runsStarted) ||
    !isNonNegativeInteger(value.runsWon) ||
    !validateChamber(value.bestRoom) ||
    readUpgradeIds(value.unlockedUpgradeIds) === null ||
    !isNonNegativeInteger(value.currency)
  ) {
    return false
  }
  const owned = readItemIds(value.ownedItemIds)
  const progress = readDifficultyProgress(
    value.bestChamberByDifficulty,
    validateChamber,
  )
  if (
    owned === null ||
    !STARTER_ITEM_IDS.every((id) => owned.includes(id)) ||
    readValidLoadout(value.loadout, owned) === null ||
    progress === null ||
    !isDifficultyRank(value.highestDifficultyUnlocked) ||
    !isCompletedDifficultyRank(value.highestDifficultyCleared) ||
    !isDifficultyRank(value.lastSelectedDifficulty)
  ) {
    return false
  }
  const legacyUnlocked = Math.min(5, value.highestDifficultyCleared + 1)
  const validTwoModeProgress =
    value.highestDifficultyUnlocked <= 2 &&
    value.highestDifficultyCleared <= 2 &&
    value.highestDifficultyUnlocked >=
      Math.min(2, value.highestDifficultyCleared + 1)
  return (
    (value.highestDifficultyUnlocked === legacyUnlocked ||
      validTwoModeProgress) &&
    value.lastSelectedDifficulty <= value.highestDifficultyUnlocked
  )
}

function isMetaProgressionV4(
  value: unknown,
  validateChamber: ChamberProgressValidator = isLegacyRunBestRoom,
): value is MetaProgressionV4 {
  if (!isMetaProgressionV3(value, validateChamber) || !isRecord(value)) {
    return false
  }
  return (
    readPermanentStatLevels(value.permanentStatLevels) !== null &&
    readTrainingScenarioIds(value.completedTrainingScenarioIds) !== null &&
    typeof value.trainingPromptSeen === 'boolean'
  )
}

function readTrainingScenarioIds(value: unknown): TrainingScenarioId[] | null {
  if (
    !Array.isArray(value) ||
    value.length > TRAINING_SCENARIO_IDS.length ||
    !value.every(
      (id) =>
        typeof id === 'string' &&
        TRAINING_SCENARIO_IDS.includes(id as TrainingScenarioId),
    )
  ) {
    return null
  }
  return TRAINING_SCENARIO_IDS.filter((id) => value.includes(id))
}

function readDailyRecord(value: unknown): DailyRecord | null {
  if (!isRecord(value)) return null
  if (
    !isDailyDateKey(value.dateKey) ||
    !isDifficultyRank(value.difficulty) ||
    !isNonNegativeInteger(value.attempts) ||
    !isNonNegativeInteger(value.bestScore) ||
    !isDailyBestChamber(value.bestChamber) ||
    typeof value.won !== 'boolean' ||
    typeof value.rewardClaimed !== 'boolean' ||
    (value.biomeId !== null &&
      value.biomeId !== 'crypt' &&
      value.biomeId !== 'moon-garden') ||
    (value.bossId !== null &&
      (typeof value.bossId !== 'string' ||
        !bossIds.has(value.bossId as BossArchetypeId))) ||
    (value.rewardClaimed && !value.won) ||
    !isRecord(value.buildSnapshot)
  ) {
    return null
  }
  const snapshotLoadout = readValidLoadout(
    value.buildSnapshot.loadout,
    ITEM_IDS,
  )
  const snapshotLevels = readPermanentStatLevels(
    value.buildSnapshot.permanentStatLevels,
  )
  if (snapshotLoadout === null || snapshotLevels === null) return null
  return {
    dateKey: value.dateKey,
    difficulty: value.difficulty,
    attempts: value.attempts,
    bestScore: value.bestScore,
    bestChamber: value.bestChamber,
    won: value.won,
    rewardClaimed: value.rewardClaimed,
    biomeId: value.biomeId,
    bossId: value.bossId as BossArchetypeId | null,
    buildSnapshot: {
      loadout: snapshotLoadout,
      permanentStatLevels: snapshotLevels,
    },
  }
}

function readDailyRecords(value: unknown): DailyRecord[] | null {
  if (!Array.isArray(value) || value.length > 155) return null
  const records = value.map(readDailyRecord)
  if (records.some((record) => record === null)) return null
  const copied = records as DailyRecord[]
  const keys = copied.map((record) => `${record.dateKey}:${record.difficulty}`)
  if (new Set(keys).size !== keys.length) return null
  return copied.sort(
    (a, b) =>
      b.dateKey.localeCompare(a.dateKey, 'en') || a.difficulty - b.difficulty,
  )
}

function isMetaProgressionV5(
  value: unknown,
  validateChamber: ChamberProgressValidator = isLegacyRunBestRoom,
): value is MetaProgressionV5 {
  return (
    isMetaProgressionV4(value, validateChamber) &&
    isRecord(value) &&
    readDailyRecords(value.dailyRecords) !== null
  )
}

function isMetaProgressionV6(value: unknown): value is MetaProgressionV6 {
  if (!isMetaProgressionV5(value, isCurrentRunBestRoom) || !isRecord(value)) {
    return false
  }
  const scores = readScoreProgress(value.bestScoreByDifficulty)
  return (
    scores !== null &&
    isRecord(value.bossClears) &&
    isNonNegativeInteger(value.bossClears['grave-warden']) &&
    isNonNegativeInteger(value.bossClears['moonbriar-queen']) &&
    typeof value.firstRunTutorialSeen === 'boolean'
  )
}

function readStringIds(value: unknown, max = 128): string[] | null {
  if (
    !Array.isArray(value) ||
    value.length > max ||
    !value.every(
      (id) => typeof id === 'string' && id.length > 0 && id.length <= 64,
    )
  ) {
    return null
  }
  return [...new Set(value)]
}

function isMetaProgressionV7(value: unknown): value is MetaProgression {
  if (!isMetaProgressionV6(value) || !isRecord(value)) return false
  const weapons = readStringIds(value.unlockedWeaponIds, 16)
  const passives = readStringIds(value.unlockedPassiveIds, 64)
  return (
    weapons !== null &&
    weapons.every(isRangedWeaponId) &&
    passives !== null &&
    passives.every(isPassiveId) &&
    isRangedWeaponId(value.starterRangedWeaponId) &&
    weapons.includes(value.starterRangedWeaponId)
  )
}

export function validateSaveDataV1(value: unknown): value is SaveDataV1 {
  return (
    isRecord(value) &&
    value.version === 1 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV1(value.meta)
  )
}

export function validateSaveDataV2(value: unknown): value is SaveDataV2 {
  return (
    isRecord(value) &&
    value.version === 2 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV2(value.meta)
  )
}

export function validateSaveDataV3(value: unknown): value is SaveDataV3 {
  return (
    isRecord(value) &&
    value.version === 3 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV3(value.meta)
  )
}

export function validateSaveDataV4(value: unknown): value is SaveDataV4 {
  return (
    isRecord(value) &&
    value.version === 4 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV4(value.meta)
  )
}

export function validateSaveDataV5(value: unknown): value is SaveDataV5 {
  return (
    isRecord(value) &&
    value.version === 5 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV5(value.meta)
  )
}

export function validateSaveDataV6(value: unknown): value is SaveDataV6 {
  return (
    isRecord(value) &&
    value.version === 6 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV6(value.meta)
  )
}

export function validateSaveDataV7(value: unknown): value is SaveDataV7 {
  return (
    isRecord(value) &&
    value.version === 7 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV7(value.meta)
  )
}

export function validateSaveDataV8(value: unknown): value is SaveDataV8 {
  return (
    isRecord(value) &&
    value.version === 8 &&
    isGameSettings(value.settings) &&
    isMetaProgressionV7(value.meta)
  )
}

function copySettings(settings: GameSettings): GameSettings {
  return { ...settings }
}

function copyV2Meta(value: MetaProgressionV2): MetaProgressionV2 {
  return {
    runsStarted: value.runsStarted,
    runsWon: value.runsWon,
    bestRoom: value.bestRoom,
    unlockedUpgradeIds: [...new Set(value.unlockedUpgradeIds)],
    currency: value.currency,
    ownedItemIds: readItemIds(value.ownedItemIds) ?? [...STARTER_ITEM_IDS],
    loadout: { ...value.loadout },
  }
}

function copyV3Meta(
  value: MetaProgressionV3,
  validateChamber: ChamberProgressValidator = isLegacyRunBestRoom,
): MetaProgressionV3 {
  const progress = readDifficultyProgress(
    value.bestChamberByDifficulty,
    validateChamber,
  )
  if (progress === null) throw new TypeError('Invalid difficulty progress')
  return {
    ...copyV2Meta(value),
    highestDifficultyUnlocked: value.highestDifficultyUnlocked,
    highestDifficultyCleared: value.highestDifficultyCleared,
    lastSelectedDifficulty: value.lastSelectedDifficulty,
    bestChamberByDifficulty: progress,
  }
}

function copyV4Meta(
  value: MetaProgressionV4,
  validateChamber: ChamberProgressValidator = isLegacyRunBestRoom,
): MetaProgressionV4 {
  const levels = readPermanentStatLevels(value.permanentStatLevels)
  const completedTrainingScenarioIds = readTrainingScenarioIds(
    value.completedTrainingScenarioIds,
  )
  if (levels === null) throw new TypeError('Invalid permanent stat levels')
  if (completedTrainingScenarioIds === null) {
    throw new TypeError('Invalid completed training scenarios')
  }
  return {
    ...copyV3Meta(value, validateChamber),
    permanentStatLevels: levels,
    completedTrainingScenarioIds,
    trainingPromptSeen: value.trainingPromptSeen,
  }
}

function copyV5Meta(
  value: MetaProgressionV5,
  validateChamber: ChamberProgressValidator = isLegacyRunBestRoom,
): MetaProgressionV5 {
  const records = readDailyRecords(value.dailyRecords)
  if (records === null) throw new TypeError('Invalid daily records')
  return {
    ...copyV4Meta(value, validateChamber),
    dailyRecords: records,
  }
}

function copyV6Meta(value: MetaProgressionV6): MetaProgressionV6 {
  const scores = readScoreProgress(value.bestScoreByDifficulty)
  if (scores === null) throw new TypeError('Invalid score progress')
  return {
    ...copyV5Meta(value, isCurrentRunBestRoom),
    bestScoreByDifficulty: scores,
    bossClears: { ...value.bossClears },
    firstRunTutorialSeen: value.firstRunTutorialSeen,
  }
}

function copyCurrentSave(value: SaveDataV8): SaveDataV8 {
  const unlockedWeaponIds = readStringIds(value.meta.unlockedWeaponIds, 16)
  const unlockedPassiveIds = readStringIds(value.meta.unlockedPassiveIds, 64)
  if (unlockedWeaponIds === null || unlockedPassiveIds === null) {
    throw new TypeError('Invalid content unlocks')
  }
  return {
    version: 8,
    settings: copySettings(value.settings),
    meta: {
      ...copyV6Meta(value.meta),
      unlockedWeaponIds: [
        ...new Set([...DEFAULT_UNLOCKED_WEAPON_IDS, ...unlockedWeaponIds]),
      ],
      // Content that ships unlocked stays unlocked. A save written before a
      // free item existed must not lock a returning player out of it.
      unlockedPassiveIds: [
        ...new Set([...DEFAULT_UNLOCKED_PASSIVE_IDS, ...unlockedPassiveIds]),
      ],
      starterRangedWeaponId: value.meta.starterRangedWeaponId,
    },
  }
}

function copyV6Save(value: SaveDataV6): SaveDataV6 {
  const scores = readScoreProgress(value.meta.bestScoreByDifficulty)
  if (scores === null) throw new TypeError('Invalid score progress')
  return {
    version: 6,
    settings: copySettings(value.settings),
    meta: copyV6Meta(value.meta),
  }
}

function copyV5Save(value: SaveDataV5): SaveDataV5 {
  const records = readDailyRecords(value.meta.dailyRecords)
  if (records === null) throw new TypeError('Invalid daily records')
  return {
    version: 5,
    settings: copySettings(value.settings),
    meta: { ...copyV4Meta(value.meta), dailyRecords: records },
  }
}

function migrated(
  settings: GameSettings,
  meta: MetaProgression,
): SaveLoadResult {
  return {
    data: { version: 8, settings: copySettings(settings), meta },
    status: 'migrated',
    issues: [],
  }
}

function migrateV6Save(value: SaveDataV6): SaveLoadResult {
  const copied = copyV6Save(value)
  return migrated(copied.settings, upgradeV6Meta(copied.meta))
}

function migrateV5Save(value: SaveDataV5): SaveLoadResult {
  const copied = copyV5Save(value)
  return migrated(copied.settings, upgradeV6Meta(upgradeV5Meta(copied.meta)))
}

function migrateV4Save(value: SaveDataV4): SaveLoadResult {
  return migrated(
    value.settings,
    upgradeV6Meta(upgradeV5Meta(upgradeV4Meta(copyV4Meta(value.meta)))),
  )
}

function migrateV3Save(value: SaveDataV3): SaveLoadResult {
  return migrated(
    value.settings,
    upgradeV6Meta(
      upgradeV5Meta(upgradeV4Meta(upgradeV3Meta(copyV3Meta(value.meta)))),
    ),
  )
}

function migrateV2Save(value: SaveDataV2): SaveLoadResult {
  return migrated(
    value.settings,
    upgradeV6Meta(
      upgradeV5Meta(
        upgradeV4Meta(upgradeV3Meta(upgradeV2Meta(copyV2Meta(value.meta)))),
      ),
    ),
  )
}

function migrateV1Save(value: SaveDataV1): SaveLoadResult {
  const v2Meta: MetaProgressionV2 = {
    ...value.meta,
    unlockedUpgradeIds: [...new Set(value.meta.unlockedUpgradeIds)],
    currency: 0,
    ownedItemIds: [...STARTER_ITEM_IDS],
    loadout: { ...DEFAULT_LOADOUT },
  }
  return migrated(
    value.settings,
    upgradeV6Meta(
      upgradeV5Meta(upgradeV4Meta(upgradeV3Meta(upgradeV2Meta(v2Meta)))),
    ),
  )
}

function migrateLegacySave(value: Record<string, unknown>): SaveLoadResult {
  const defaults = createDefaultSave()
  const legacySettings = isRecord(value.settings) ? value.settings : value
  const legacyMeta = isRecord(value.meta) ? value.meta : value
  const issues: string[] = []
  const volume = legacySettings.masterVolume ?? legacySettings.volume
  const readVolume = (candidate: unknown, fallback: number, label: string) => {
    if (candidate === undefined) return fallback
    if (isVolume(candidate)) return candidate
    issues.push(`Discarded invalid legacy ${label}`)
    return fallback
  }
  const readCount = (candidate: unknown, label: string) => {
    if (candidate === undefined) return 0
    if (isNonNegativeInteger(candidate)) return candidate
    issues.push(`Discarded invalid legacy ${label}`)
    return 0
  }
  const settings: GameSettings = {
    masterVolume: readVolume(
      volume,
      defaults.settings.masterVolume,
      'master volume',
    ),
    musicVolume: readVolume(
      legacySettings.musicVolume,
      defaults.settings.musicVolume,
      'music volume',
    ),
    sfxVolume: readVolume(
      legacySettings.sfxVolume,
      defaults.settings.sfxVolume,
      'SFX volume',
    ),
    cameraShake:
      typeof (legacySettings.cameraShake ?? legacySettings.screenShake) ===
      'boolean'
        ? ((legacySettings.cameraShake ??
            legacySettings.screenShake) as boolean)
        : defaults.settings.cameraShake,
  }
  const parsedUnlocks = readUpgradeIds(
    legacyMeta.unlockedUpgradeIds ?? legacyMeta.unlockedUpgrades ?? [],
  )
  const readOwned = readItemIds(legacyMeta.ownedItemIds ?? STARTER_ITEM_IDS)
  const ownedItemIds =
    readOwned !== null && STARTER_ITEM_IDS.every((id) => readOwned.includes(id))
      ? readOwned
      : [...STARTER_ITEM_IDS]
  const loadout =
    readValidLoadout(legacyMeta.loadout ?? DEFAULT_LOADOUT, ownedItemIds) ??
    ({ ...DEFAULT_LOADOUT } as EquipmentLoadout)
  const v2Meta: MetaProgressionV2 = {
    runsStarted: readCount(legacyMeta.runsStarted, 'run count'),
    runsWon: readCount(legacyMeta.runsWon ?? legacyMeta.wins, 'win count'),
    bestRoom: isLegacyBestRoom(legacyMeta.bestRoom) ? legacyMeta.bestRoom : 0,
    unlockedUpgradeIds: parsedUnlocks ?? [],
    currency: readCount(legacyMeta.currency, 'currency'),
    ownedItemIds,
    loadout,
  }
  const result = migrated(
    settings,
    upgradeV6Meta(
      upgradeV5Meta(upgradeV4Meta(upgradeV3Meta(upgradeV2Meta(v2Meta)))),
    ),
  )
  return { ...result, issues }
}

function resetResult(issue: string): SaveLoadResult {
  return { data: createDefaultSave(), status: 'reset', issues: [issue] }
}

export function loadSave(raw: unknown): SaveLoadResult {
  if (raw === null || raw === undefined || raw === '') {
    return resetResult('No saved data was found')
  }
  let parsed: unknown = raw
  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw) as unknown
    } catch {
      return resetResult('Saved data is not valid JSON')
    }
  }
  if (!isRecord(parsed)) return resetResult('Saved data must be an object')

  if (parsed.version === 8) {
    if (!validateSaveDataV8(parsed))
      return resetResult('Version 8 saved data failed validation')
    return { data: copyCurrentSave(parsed), status: 'current', issues: [] }
  }
  if (parsed.version === 7) {
    if (!validateSaveDataV7(parsed))
      return resetResult('Version 7 saved data failed validation')
    return migrated(parsed.settings, {
      ...parsed.meta,
      unlockedWeaponIds: [
        ...new Set([
          ...DEFAULT_UNLOCKED_WEAPON_IDS,
          ...parsed.meta.unlockedWeaponIds,
        ]),
      ],
      unlockedPassiveIds: [...parsed.meta.unlockedPassiveIds],
    })
  }
  if (parsed.version === 6) {
    if (!validateSaveDataV6(parsed))
      return resetResult('Version 6 saved data failed validation')
    return migrateV6Save(parsed)
  }
  if (parsed.version === 5) {
    if (!validateSaveDataV5(parsed))
      return resetResult('Version 5 saved data failed validation')
    return migrateV5Save(parsed)
  }
  if (parsed.version === 4) {
    if (!validateSaveDataV4(parsed))
      return resetResult('Version 4 saved data failed validation')
    return migrateV4Save(parsed)
  }
  if (parsed.version === 3) {
    if (!validateSaveDataV3(parsed))
      return resetResult('Version 3 saved data failed validation')
    return migrateV3Save(parsed)
  }
  if (parsed.version === 2) {
    if (!validateSaveDataV2(parsed))
      return resetResult('Version 2 saved data failed validation')
    return migrateV2Save(parsed)
  }
  if (parsed.version === 1) {
    if (!validateSaveDataV1(parsed))
      return resetResult('Version 1 saved data failed validation')
    return migrateV1Save(parsed)
  }
  if (parsed.version === 0 || parsed.version === undefined) {
    return migrateLegacySave(parsed)
  }
  return resetResult('Saved data has an unsupported version')
}

export function serializeSave(data: SaveDataV8): string {
  if (!validateSaveDataV8(data)) {
    throw new TypeError('Cannot serialize invalid save data')
  }
  return JSON.stringify(copyCurrentSave(data))
}
