import { uniformFloat64 } from 'pure-rand/distribution/uniformFloat64'
import { uniformInt } from 'pure-rand/distribution/uniformInt'
import { xoroshiro128plus } from 'pure-rand/generator/xoroshiro128plus'

import type { RunSeed, SeedInput } from './types'

export type RunRandomStreamName =
  'layout' | 'spawns' | 'rewards' | 'map' | 'elites' | 'mutations'

export interface RandomStream {
  nextFloat(): number
  nextInt(minInclusive: number, maxInclusive: number): number
  pick<T>(values: readonly T[]): T
  shuffle<T>(values: readonly T[]): T[]
}

export interface RunRandomStreams {
  readonly layout: RandomStream
  readonly spawns: RandomStream
  readonly rewards: RandomStream
  readonly map: RandomStream
  readonly elites: RandomStream
  readonly mutations: RandomStream
}

export function normalizeRunSeed(seed: SeedInput): RunSeed {
  if (typeof seed === 'number') {
    if (!Number.isFinite(seed)) {
      throw new RangeError('Numeric run seeds must be finite')
    }
    return Object.is(seed, -0) ? '0' : String(seed)
  }

  const normalized = seed.trim()
  return normalized.length > 0 ? normalized : 'stillseen'
}

/** Stable 32-bit FNV-1a plus an avalanche finalizer. */
export function hashRunSeed(seed: RunSeed, streamName: string): number {
  const input = `${seed}\u0000${streamName}`
  let hash = 0x811c9dc5

  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }

  hash ^= hash >>> 16
  hash = Math.imul(hash, 0x7feb352d)
  hash ^= hash >>> 15
  hash = Math.imul(hash, 0x846ca68b)
  hash ^= hash >>> 16
  return hash | 0
}

export function createRandomStream(
  seed: SeedInput,
  streamName: string,
): RandomStream {
  const normalizedSeed = normalizeRunSeed(seed)
  const generator = xoroshiro128plus(hashRunSeed(normalizedSeed, streamName))

  return {
    nextFloat: () => uniformFloat64(generator),
    nextInt: (minInclusive, maxInclusive) => {
      if (
        !Number.isSafeInteger(minInclusive) ||
        !Number.isSafeInteger(maxInclusive) ||
        minInclusive > maxInclusive
      ) {
        throw new RangeError(
          'Random integer bounds must be ordered safe integers',
        )
      }
      return uniformInt(generator, minInclusive, maxInclusive)
    },
    pick: <T>(values: readonly T[]): T => {
      if (values.length === 0) {
        throw new RangeError('Cannot pick from an empty collection')
      }
      return values[uniformInt(generator, 0, values.length - 1)] as T
    },
    shuffle: <T>(values: readonly T[]): T[] => {
      const shuffled = [...values]
      for (let index = shuffled.length - 1; index > 0; index -= 1) {
        const replacement = uniformInt(generator, 0, index)
        ;[shuffled[index], shuffled[replacement]] = [
          shuffled[replacement] as T,
          shuffled[index] as T,
        ]
      }
      return shuffled
    },
  }
}

export function createRunRandomStreams(seed: SeedInput): RunRandomStreams {
  return {
    layout: createRandomStream(seed, 'layout'),
    spawns: createRandomStream(seed, 'spawns'),
    rewards: createRandomStream(seed, 'rewards'),
    map: createRandomStream(seed, 'map'),
    elites: createRandomStream(seed, 'elites'),
    mutations: createRandomStream(seed, 'mutations'),
  }
}
