/**
 * The endless run.
 *
 * There are no sectors any more. A run is one unbroken fight whose only score
 * is how long you lasted, so every curve here is driven by a single input —
 * seconds survived — rather than by a chamber index. That is the whole design:
 * the clock is the difficulty, the clock is the score, and the player can read
 * both off the same number.
 *
 * Upgrades arrive by levelling, not by clearing rooms, because there are no
 * rooms to clear. Kills pay experience; experience pays a rune choice.
 *
 * Pure and deterministic: no Three.js, no store, no clock of its own. Every
 * function is a plain map from elapsed time (or a kill tally) to a number or a
 * roster, so the entire difficulty, cast, and reward pacing is unit-testable
 * from one file.
 */

import { ELITE_AFFIX_IDS } from './encounterModifiers'
import type { BossArchetypeId, EliteAffixId, EnemyArchetypeId } from './types'

function clampNumber(value: number, min: number, max: number): number {
  if (!Number.isFinite(value)) return min
  return value < min ? min : value > max ? max : value
}

/**
 * A stable unit float from two integers.
 *
 * Integer ops only, deliberately: the obvious `Math.sin`-based hash has
 * engine-defined precision, so the same wave would elite differently in two
 * browsers. This module's contract is that its output is a pure function of
 * its inputs, and that has to survive leaving Chromium.
 */
function hashUnit(a: number, b: number, salt: number): number {
  const x = Math.floor(a) | 0
  const y = Math.floor(b) | 0
  let h = Math.imul(x, 0x27d4eb2d) ^ Math.imul(y, 0x165667b1) ^ (salt | 0)
  h = Math.imul(h ^ (h >>> 15), 0x2545f491)
  h ^= h >>> 13
  return (h >>> 0) / 0x100000000
}

/** Seconds survived, floored at zero and safe against a broken clock. */
export function safeElapsed(elapsedSeconds: number): number {
  if (!Number.isFinite(elapsedSeconds) || elapsedSeconds < 0) return 0
  return elapsedSeconds
}

// ---------------------------------------------------------------------------
// Pressure
// ---------------------------------------------------------------------------

/** The opening minute teaches movement and auto-weapon spacing before the
 * normal endless pressure curve takes full control. */
export const OPENING_SURVIVAL_SECONDS = 60

/** Prevents an authored ranged spawn from landing damage before the player has
 * had time to read the arena and establish movement. */
export const OPENING_DAMAGE_GRACE_SECONDS = 8

/** The opening should already read as a survivor swarm. Low health keeps this
 * crowd satisfying instead of punitive while the player learns the weapon. */
export const OPENING_ENEMY_CAP = 12

/** Standard opening enemies stay inside the weakest starter's one-shot budget
 * before health begins to catch up with the player's growing build. */
export const OPENING_ONE_SHOT_SECONDS = 45
export const OPENING_HEALTH_RAMP_SECONDS = 150

const OPENING_DAMAGE_FLOOR = 0.45

/**
 * Gap between arrivals. Decays toward a floor rather than stepping, so the
 * ramp is felt as continuous pressure instead of discrete difficulty tiers.
 */
export function spawnIntervalMs(elapsedSeconds: number): number {
  const decayed = 1200 * Math.exp(-safeElapsed(elapsedSeconds) / 360)
  return clampNumber(decayed, 300, 1200)
}

/** Bodies per arrival. */
export function waveSize(elapsedSeconds: number): number {
  return clampNumber(3 + Math.floor(safeElapsed(elapsedSeconds) / 60), 3, 12)
}

/**
 * Ceiling on bodies alive at once.
 *
 * A frame-budget guard as much as a difficulty knob: every hostile is a rigged
 * mesh, and an uncapped survivor spawner will bury a machine long before it
 * threatens a good player. Arrivals over the cap are skipped, never queued — a
 * backlog that drains the instant a kill lands is worse than a brief lull.
 */
export function activeEnemyCap(elapsedSeconds: number): number {
  const elapsed = safeElapsed(elapsedSeconds)
  const baseline = clampNumber(18 + Math.floor(elapsed / 35), 18, 56)
  if (elapsed >= OPENING_SURVIVAL_SECONDS) return baseline

  // Arrive at the unmodified cap exactly on the minute boundary. Keeping this
  // continuous avoids a sudden crowd dump when opening protection expires.
  const boundaryCap = clampNumber(
    18 + Math.floor(OPENING_SURVIVAL_SECONDS / 35),
    18,
    56,
  )
  const openingCap =
    OPENING_ENEMY_CAP +
    Math.floor(
      ((boundaryCap - OPENING_ENEMY_CAP) * elapsed) / OPENING_SURVIVAL_SECONDS,
    )
  return Math.min(baseline, openingCap)
}

/**
 * Health scaling. The dominant difficulty lever — more health is what turns a
 * crowd the player could previously carve through into one they have to
 * position against.
 */
export function enemyHealthMultiplier(elapsedSeconds: number): number {
  const elapsed = safeElapsed(elapsedSeconds)
  const baseline = clampNumber(1 + elapsed / 240, 1, 8)
  if (elapsed <= OPENING_ONE_SHOT_SECONDS) return 0.25
  if (elapsed >= OPENING_HEALTH_RAMP_SECONDS) return baseline

  const progress =
    (elapsed - OPENING_ONE_SHOT_SECONDS) /
    (OPENING_HEALTH_RAMP_SECONDS - OPENING_ONE_SHOT_SECONDS)
  return 0.25 + (baseline - 0.25) * progress
}

/**
 * Damage scaling, deliberately gentler than health. Ramping damage as hard as
 * health turns the late run into one-shot deaths, which reads as unfair rather
 * than difficult.
 */
export function enemyDamageMultiplier(elapsedSeconds: number): number {
  const elapsed = safeElapsed(elapsedSeconds)
  const baseline = clampNumber(1 + elapsed / 600, 1, 3)
  if (elapsed >= OPENING_SURVIVAL_SECONDS) return baseline
  if (elapsed < OPENING_DAMAGE_GRACE_SECONDS) return 0

  const openingProgress = clampNumber(
    (elapsed - OPENING_DAMAGE_GRACE_SECONDS) /
      (OPENING_SURVIVAL_SECONDS - OPENING_DAMAGE_GRACE_SECONDS),
    0,
    1,
  )
  const protection =
    OPENING_DAMAGE_FLOOR + (1 - OPENING_DAMAGE_FLOOR) * openingProgress
  return baseline * protection
}

// ---------------------------------------------------------------------------
// Roster
// ---------------------------------------------------------------------------

/**
 * Which hostiles the survivor spawner may draw from, by elapsed time.
 *
 * The roster used to be read off the chamber the run started in, which in a
 * mode with exactly one chamber meant every run — in every arena, for its whole
 * length — fought the same two archetypes. Time drives it instead, so the
 * clock introduces the cast the same way it introduces everything else.
 *
 * Order matters. The spawner walks this array with `(wave + index) % length`,
 * so entries are interleaved rather than clustered: a single arrival should
 * read as a mixed squad, not four of one thing followed by four of another.
 * Weight is expressed by repetition — husks stay the bulk of every tier
 * because the newcomers are all meant to be read against a familiar baseline.
 *
 * The gaze rule is the pacing here, not the stat line. Each tier adds exactly
 * one archetype that answers the optic differently, and leaves a gap before the
 * next so the player learns one exception at a time:
 *
 * | at    | joins        | its answer to the optic          |
 * | ----- | ------------ | -------------------------------- |
 * | 0:00  | husk, archer | freezes                          |
 * | 2:00  | crypt-brute  | freezes, but soaks the window    |
 * | 4:00  | gaze-stalker | inverts — looking at it wakes it |
 * | 7:00  | blind-thrall | immune, and fast                 |
 * | 10:00 | veil-breaker | breaks out, and frees the frozen |
 */
const SURVIVAL_ROSTER_TIERS: readonly {
  readonly atSeconds: number
  readonly roster: readonly EnemyArchetypeId[]
}[] = [
  {
    atSeconds: 0,
    roster: ['grave-husk', 'grave-husk', 'bone-archer', 'grave-husk'],
  },
  {
    atSeconds: 120,
    roster: [
      'grave-husk',
      'bone-archer',
      'grave-husk',
      'crypt-brute',
      'grave-husk',
      'bone-archer',
      'grave-husk',
    ],
  },
  {
    atSeconds: 240,
    roster: [
      'grave-husk',
      'bone-archer',
      'gaze-stalker',
      'grave-husk',
      'crypt-brute',
      'grave-husk',
      'bone-archer',
      'grave-husk',
    ],
  },
  {
    atSeconds: 420,
    roster: [
      'grave-husk',
      'bone-archer',
      'gaze-stalker',
      'blind-thrall',
      'grave-husk',
      'crypt-brute',
      'grave-husk',
      'bone-archer',
      'gaze-stalker',
      'blind-thrall',
      'grave-husk',
      'crypt-brute',
    ],
  },
  {
    atSeconds: 600,
    roster: [
      'grave-husk',
      'bone-archer',
      'gaze-stalker',
      'blind-thrall',
      'grave-husk',
      'crypt-brute',
      'veil-breaker',
      'bone-archer',
      'gaze-stalker',
      'blind-thrall',
      'grave-husk',
      'crypt-brute',
    ],
  },
]

/**
 * The archetypes on offer right now. Never empty, and stable for the whole of
 * a tier so a wave cannot change cast mid-arrival.
 */
export function survivalRoster(
  elapsedSeconds: number,
): readonly EnemyArchetypeId[] {
  const elapsed = safeElapsed(elapsedSeconds)
  let roster = SURVIVAL_ROSTER_TIERS[0].roster
  for (const tier of SURVIVAL_ROSTER_TIERS) {
    if (elapsed < tier.atSeconds) break
    roster = tier.roster
  }
  return roster
}

// ---------------------------------------------------------------------------
// Elites
// ---------------------------------------------------------------------------

/**
 * How long the run stays elite-free.
 *
 * An elite is read by its badge and its behaviour, and both are noise while the
 * player is still learning that looking at something stops it. It also overlaps
 * the opening damage grace, so the first affix lands only once the fight is
 * paying full price anyway.
 */
export const ELITE_GRACE_SECONDS = 90

/** Ceiling on elite density. Past this an arrival stops reading as a standout. */
const ELITE_CHANCE_CAP = 0.2

/** Odds that any one arrival carries an affix. */
export function survivalEliteChance(elapsedSeconds: number): number {
  const elapsed = safeElapsed(elapsedSeconds)
  if (elapsed < ELITE_GRACE_SECONDS) return 0
  return clampNumber(
    ((elapsed - ELITE_GRACE_SECONDS) / 540) * ELITE_CHANCE_CAP,
    0,
    ELITE_CHANCE_CAP,
  )
}

/**
 * The affix on a specific arrival, or null for a plain one.
 *
 * Keyed on the wave and the slot inside it rather than on a running counter, so
 * a wave that gets skipped at the population cap cannot shift every later
 * arrival's roll — the same slot of the same wave is always the same enemy.
 */
export function survivalEliteAffix(
  elapsedSeconds: number,
  waveIndex: number,
  slotIndex: number,
): EliteAffixId | null {
  if (
    hashUnit(waveIndex, slotIndex, 0x5e) >= survivalEliteChance(elapsedSeconds)
  )
    return null
  const pick = Math.floor(
    hashUnit(waveIndex, slotIndex, 0xaf) * ELITE_AFFIX_IDS.length,
  )
  return ELITE_AFFIX_IDS[Math.min(pick, ELITE_AFFIX_IDS.length - 1)]
}

// ---------------------------------------------------------------------------
// Bosses
// ---------------------------------------------------------------------------

/** A boss arrives on every one of these boundaries. */
export const BOSS_INTERVAL_SECONDS = 300

/** How many bosses should have arrived by now. */
export function bossesDueBy(elapsedSeconds: number): number {
  return Math.floor(safeElapsed(elapsedSeconds) / BOSS_INTERVAL_SECONDS)
}

/**
 * The boss the run is paced toward. Nothing ends here — the clock keeps
 * running and bosses keep arriving — but it is the last milestone the lobby
 * advertises, so it is the one that gets announced differently.
 */
export const FINAL_SURVIVAL_BOSS = 4

/** Four readable milestone identities, then the same sequence returns stronger. */
export const SURVIVAL_BOSS_SEQUENCE = [
  'grave-warden',
  'moonbriar-queen',
  'parallax-seraph',
  'null-crown',
] as const satisfies readonly BossArchetypeId[]

export function survivalBossArchetype(bossNumber: number): BossArchetypeId {
  const n = Math.max(
    1,
    Math.floor(Number.isFinite(bossNumber) ? bossNumber : 1),
  )
  return SURVIVAL_BOSS_SEQUENCE[(n - 1) % SURVIVAL_BOSS_SEQUENCE.length]
}

/**
 * The affix carried by the nth boss, or null for a plain one.
 *
 * The first four appearances introduce one identity each without an affix.
 * Endless rotations after the 20-minute milestone add variants.
 */
export function survivalBossAffix(bossNumber: number): EliteAffixId | null {
  const n = clampNumber(Math.floor(bossNumber), 1, 99)
  if (n <= SURVIVAL_BOSS_SEQUENCE.length) return null
  return ELITE_AFFIX_IDS[
    (n - SURVIVAL_BOSS_SEQUENCE.length - 1) % ELITE_AFFIX_IDS.length
  ]
}

/** Seconds until the next boss. Zero exactly on the boundary. */
export function secondsToNextBoss(elapsedSeconds: number): number {
  const elapsed = safeElapsed(elapsedSeconds)
  const next = (bossesDueBy(elapsed) + 1) * BOSS_INTERVAL_SECONDS
  return Math.max(0, next - elapsed)
}

/**
 * What the first boss is worth against a normal body of the same minute.
 * A boss already carries roughly nine times a husk's base health, so this is
 * the margin that makes it a wall rather than a large husk.
 */
const BOSS_BASE_HEALTH_MULTIPLIER = 1.55

/** Added per boss after the first. */
const BOSS_HEALTH_STEP = 0.35

/**
 * Health multiplier for the nth boss (1-based), on top of the time ramp.
 * Each one has to read as a step up from the last, not just a bigger crowd.
 *
 * The step used to apply only from the fifth boss on, which meant the four
 * bosses a player actually reaches — 5, 10, 15 and 20 minutes — were all worth
 * exactly the same multiplier and differed only by the clock they arrived on.
 * The milestone the whole run is paced around read as four repeats of one
 * fight, so the step now applies from the second boss.
 */
export function bossHealthMultiplier(bossNumber: number): number {
  const n = clampNumber(Math.floor(bossNumber), 1, 99)
  return BOSS_BASE_HEALTH_MULTIPLIER + (n - 1) * BOSS_HEALTH_STEP
}

// ---------------------------------------------------------------------------
// Experience and levels
// ---------------------------------------------------------------------------

export type KillKind = 'normal' | 'elite' | 'boss'

/** Experience a kill pays. */
export function experienceForKill(kind: KillKind): number {
  if (kind === 'boss') return 40
  if (kind === 'elite') return 5
  return 1
}

/**
 * Experience needed to go from `level` to the next one.
 *
 * Linear rather than exponential: the spawn rate is already climbing, so a
 * flat-ish curve keeps level-ups arriving at a roughly steady pace instead of
 * drying up exactly when the run gets hard.
 */
export function experienceToNextLevel(level: number): number {
  const safe = clampNumber(Math.floor(level), 1, 999)
  return 3 + safe * 3
}

export interface LevelProgress {
  readonly level: number
  /** Experience banked toward the next level. */
  readonly into: number
  /** Experience the next level costs. */
  readonly required: number
}

/**
 * Resolves total lifetime experience into a level and the progress bar under
 * it. Derived rather than stored so a level can never drift from its total.
 */
export function resolveLevel(totalExperience: number): LevelProgress {
  let remaining = Math.max(
    0,
    Number.isFinite(totalExperience) ? Math.floor(totalExperience) : 0,
  )
  let level = 1
  // 999 is the clamp in experienceToNextLevel; past it the loop cannot end.
  while (level < 999) {
    const cost = experienceToNextLevel(level)
    if (remaining < cost) break
    remaining -= cost
    level += 1
  }
  return { level, into: remaining, required: experienceToNextLevel(level) }
}

// ---------------------------------------------------------------------------
// Payout
// ---------------------------------------------------------------------------

export interface RunTally {
  readonly survivedSeconds: number
  readonly kills: number
  readonly bossKills: number
}

/**
 * Data shards banked from a run.
 *
 * Time is the headline term because time is the score, but kills and bosses
 * carry real weight too — otherwise the optimal run is to walk in circles and
 * never fight, which is exactly the degenerate strategy an endless survival
 * mode invites.
 */
export function calculateRunShards({
  survivedSeconds,
  kills,
  bossKills,
}: RunTally): number {
  const seconds = safeElapsed(survivedSeconds)
  const safeKills = Math.max(0, Number.isFinite(kills) ? Math.floor(kills) : 0)
  const safeBosses = Math.max(
    0,
    Number.isFinite(bossKills) ? Math.floor(bossKills) : 0,
  )
  return Math.floor(seconds * 1.2) + safeKills * 2 + safeBosses * 60
}

/** `M:SS` for the HUD and the result card. */
export function formatSurvivalTime(elapsedSeconds: number): string {
  const whole = Math.floor(safeElapsed(elapsedSeconds))
  const minutes = Math.floor(whole / 60)
  return `${minutes}:${String(whole % 60).padStart(2, '0')}`
}

/**
 * The runes offered on a level-up.
 *
 * Offerings used to be a fixed per-chamber schedule. With no chambers, the
 * level itself rotates a stable order, so two runs on one seed offer the same
 * things at the same levels while a single run never repeats an offer it just
 * made. Already-owned runes drop out until there is nothing left to pick, at
 * which point repeats are allowed rather than handing back an empty choice.
 */
export function levelUpChoices<T>(
  order: readonly T[],
  owned: readonly T[],
  level: number,
  count = 3,
): T[] {
  if (order.length === 0) return []
  const rotation =
    ((((Math.floor(level) || 1) * count) % order.length) + order.length) %
    order.length
  const rotated = [...order.slice(rotation), ...order.slice(0, rotation)]
  const fresh = rotated.filter((entry) => !owned.includes(entry))
  const pool = fresh.length >= count ? fresh : rotated
  return pool.slice(0, Math.min(count, pool.length))
}
