import type { AttackDirectorTier } from './attackDirector'
import { getCombatScaling } from './difficulty'
import type { ChamberLevel, DifficultyRank } from './types'

export interface EncounterPressureProfile {
  readonly chamber: number
  readonly difficulty: DifficultyRank
  readonly healthMultiplier: number
  readonly weakEnemyHealthMultiplier: number
  readonly damageMultiplier: number
  readonly moveSpeedMultiplier: number
  readonly windupMultiplier: number
  readonly recoveryMultiplier: number
  readonly projectileSpeedMultiplier: number
  readonly bruteChargeImpulse: number
  readonly boneArcherSpreads: readonly number[]
}

const profileCache = new Map<string, EncounterPressureProfile>()

export function getPressureAdjustedMoveSpeed(
  baseSpeed: number,
  pressure: Pick<EncounterPressureProfile, 'moveSpeedMultiplier'>,
): number {
  return baseSpeed * pressure.moveSpeedMultiplier
}

function toChamber(encounter: AttackDirectorTier): ChamberLevel {
  return encounter === 'boss' ? 10 : encounter
}

export function getEncounterPressureProfile(
  encounter: AttackDirectorTier,
  difficulty: DifficultyRank = 1,
  absoluteChamber?: number,
): EncounterPressureProfile {
  const authoredChamber = toChamber(encounter)
  const scalingChamber = absoluteChamber ?? authoredChamber
  const cacheKey = `${authoredChamber}:${difficulty}:${scalingChamber}`
  const cached = profileCache.get(cacheKey)
  if (cached !== undefined) return cached

  const scaling = getCombatScaling(scalingChamber, difficulty)
  const spreads = Object.freeze(
    authoredChamber >= 3 ? [-0.12, 0, 0.12] : [0],
  ) as readonly number[]
  const profile = Object.freeze({
    ...scaling,
    bruteChargeImpulse:
      14 * (1 + 0.06 * (authoredChamber - 1)) * scaling.moveSpeedMultiplier,
    boneArcherSpreads: spreads,
  })
  profileCache.set(cacheKey, profile)
  return profile
}
