export type ToneName =
  | 'attack'
  | 'dash'
  | 'hit'
  | 'hurt'
  | 'freeze'
  | 'warning'
  | 'warning-melee'
  | 'warning-ranged'
  | 'warning-boss'
  | 'dash-ready'
  | 'footstep'
  | 'shot'
  | 'player-shot'
  | 'death'
  | 'room-start'
  | 'room-clear'
  | 'reward'
  | 'victory'

export type MusicScene = 'menu' | 'combat' | 'boss' | 'defeat' | 'none'

export type WeaponAudioId =
  | 'pulse-carbine'
  | 'scatter-cannon'
  | 'micro-missiles'
  | 'rail-lance'
  | 'arc-emitter'
  | 'orbit-drone'

export type EnemyAttackKind = 'melee' | 'brute' | 'ranged' | 'boss'
export type EnemyFireKind = Extract<EnemyAttackKind, 'ranged' | 'boss'>

export type ImpactTier =
  'normal' | 'critical' | 'kill' | 'boss-kill' | 'player-hit' | 'wall'

export interface ImpactAudioEvent {
  readonly tier: ImpactTier
  readonly pan?: number
  readonly source?: 'player' | 'enemy'
  readonly weaponId?: WeaponAudioId
}

export interface AudioMix {
  readonly master: number
  readonly music: number
  readonly sfx: number
  readonly ui: number
}

