const IMPACT_MERGE_SECONDS = 0.035
const MUSIC_CROSSFADE_SECONDS = 0.9
const MUSIC_PROGRAM_GAIN = 0.22
const SILENCE_GAIN = 0.0001

type VoiceClass = 'sfx' | 'impact'
type DestinationBus = 'sfx' | 'ui'

interface ActiveVoice {
  readonly className: VoiceClass
  readonly priority: number
  stop: () => void
}

interface MusicPlayback {
  readonly scene: Exclude<MusicScene, 'none'>
  readonly source: AudioBufferSourceNode
  readonly gain: GainNode
  stopping: boolean
}

function clampUnit(value: number): number {
  return Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0))
}

function clampPan(value: number): number {
  return Math.max(-1, Math.min(1, Number.isFinite(value) ? value : 0))
}

function decibelsToGain(decibels: number): number {
  return Math.pow(10, Math.min(0, decibels) / 20)
}

function audioAssetUrl(path: string): string {
  return `${import.meta.env.BASE_URL}assets/audio/${path}`
}

function equalPowerCurve(
  fadeIn: boolean,
  maximumGain = MUSIC_PROGRAM_GAIN,
): Float32Array {
  const points = 32
  return Float32Array.from({ length: points }, (_, index) => {
    const phase = index / (points - 1)
    const level = fadeIn
      ? Math.sin((phase * Math.PI) / 2)
      : Math.cos((phase * Math.PI) / 2)
    return Math.max(SILENCE_GAIN, level * maximumGain)
  })
}

export class AudioEngine {
  private context: AudioContext | null = null
  private masterBus: GainNode | null = null
  private musicBus: GainNode | null = null
  private musicDuck: GainNode | null = null
  private sfxBus: GainNode | null = null
  private uiBus: GainNode | null = null
  private mix: AudioMix = { ...DEFAULT_MIX }
  private contextCreationFailed = false
  private preloadPromise: Promise<void> | null = null
  private readonly buffers = new Map<string, AudioBuffer>()
  private readonly variationIndices = new Map<string, number>()
  private readonly lastPlayedAt = new Map<string, number>()
  private readonly activeVoices = new Set<ActiveVoice>()
  private requestedMusicScene: MusicScene = 'none'
  private currentMusic: MusicPlayback | null = null
  private readonly musicPlaybacks = new Set<MusicPlayback>()
  private lastMergedImpactAt = Number.NEGATIVE_INFINITY
  private heldMusicDuckGain = 1
  private resumeRetryArmed = false
  private readonly retryUnlock = () => {
    this.disarmResumeRetry()
    void this.unlock()
  }

  async unlock(signal?: AbortSignal): Promise<void> {
    const context = this.ensureContext()
    if (!context) return

    const resume =
      context.state === 'suspended'
        ? context.resume().catch(() => undefined)
        : Promise.resolve()
    await Promise.all([resume, this.preload(signal)])
    if (context.state === 'running') {
      this.disarmResumeRetry()
      this.applyHeldMusicDuck(0)
      this.startMusicIfReady()
    } else {
      this.armResumeRetry()
    }
  }

  private ensureContext(): AudioContext | null {
    if (this.context) return this.context
    if (this.contextCreationFailed) return null

    const primedContext =
      typeof window === 'undefined'
        ? undefined
        : window.__STILLSEEN_PRIMED_AUDIO_CONTEXT__
    if (primedContext && typeof window !== 'undefined') {
      window.__STILLSEEN_PRIMED_AUDIO_CONTEXT__ = undefined
    }
    if (primedContext && primedContext.state !== 'closed') {
      try {
        this.initializeGraph(primedContext)
        return primedContext
      } catch {
        this.clearGraph()
      }
    }

    const AudioContextConstructor = globalThis.AudioContext
    if (typeof AudioContextConstructor !== 'function') {
      this.contextCreationFailed = true
      return null
    }

    try {
      const context = new AudioContextConstructor()
      this.initializeGraph(context)
      return context
    } catch {
      this.clearGraph()
      this.contextCreationFailed = true
      return null
    }
  }

  private initializeGraph(context: AudioContext): void {
    const masterBus = context.createGain()
    const musicBus = context.createGain()
    const musicDuck = context.createGain()
    const sfxBus = context.createGain()
    const uiBus = context.createGain()
    const limiter = context.createDynamicsCompressor()

    masterBus.gain.value = this.mix.master
    musicBus.gain.value = this.mix.music
    musicDuck.gain.value = this.heldMusicDuckGain
    sfxBus.gain.value = this.mix.sfx
    uiBus.gain.value = this.mix.ui

    limiter.threshold.value = -3
    limiter.knee.value = 0
    limiter.ratio.value = 20
    limiter.attack.value = 0.003
    limiter.release.value = 0.15

    musicDuck.connect(musicBus)
    musicBus.connect(masterBus)
    sfxBus.connect(masterBus)
    uiBus.connect(masterBus)
    masterBus.connect(limiter)
    limiter.connect(context.destination)

    this.context = context
    this.masterBus = masterBus
    this.musicBus = musicBus
    this.musicDuck = musicDuck
    this.sfxBus = sfxBus
    this.uiBus = uiBus
  }

  private clearGraph(): void {
    this.context = null
    this.masterBus = null
    this.musicBus = null
    this.musicDuck = null
    this.sfxBus = null
    this.uiBus = null
  }

  private preload(signal?: AbortSignal): Promise<void> {
    if (this.preloadPromise) return this.preloadPromise
    const context = this.context
    if (!context || typeof fetch !== 'function') {
      this.preloadPromise = Promise.resolve()
      return this.preloadPromise
    }

    const paths = new Set<string>([
      ...Object.values(MUSIC_PATHS),
      ...Object.values(SAMPLE_VARIANTS).flatMap((cueVariants) =>
        cueVariants.map((variant) => variant.path),
      ),
      ...Object.values(AUDIO_ASSET_PATHS.sfx).flat(),
    ])
    const promise = Promise.all(
      [...paths].map(async (path) => {
        try {
          const response = signal
            ? await fetch(audioAssetUrl(path), { signal })
            : await fetch(audioAssetUrl(path))
          if (!response.ok) return
          const encoded = await response.arrayBuffer()
          const buffer = await context.decodeAudioData(encoded)
          this.buffers.set(path, buffer)
        } catch {
          // A missing or unsupported derivative uses its synthesized cue.
        }
      }),
    ).then(() => undefined)
    this.preloadPromise = promise
    void promise.then(() => {
      if (signal?.aborted && this.preloadPromise === promise) {
        this.preloadPromise = null
      }
    })
    return promise
  }

  /** Stops the audio timeline while a hidden tab cannot present the game. */
  suspendForHiddenTab(): void {
    const context = this.context
    if (!context || context.state !== 'running') return
    void context.suspend().catch(() => undefined)
  }

  /** Resumes the same music scene without spawning a duplicate loop. */
  resumeFromHiddenTab(): void {
    const context = this.context
    if (!context || context.state !== 'suspended') return
    void context
      .resume()
      .then(() => {
        this.applyHeldMusicDuck(0)
        this.startMusicIfReady()
      })
      .catch(() => this.armResumeRetry())
  }

  setMix(next: Partial<AudioMix>): void {
    this.mix = {
      master:
        next.master === undefined ? this.mix.master : clampUnit(next.master),
      music: next.music === undefined ? this.mix.music : clampUnit(next.music),
      sfx: next.sfx === undefined ? this.mix.sfx : clampUnit(next.sfx),
      ui: next.ui === undefined ? this.mix.ui : clampUnit(next.ui),
    }
    const now = this.context?.currentTime ?? 0
    this.masterBus?.gain.setTargetAtTime(this.mix.master, now, 0.02)
    this.musicBus?.gain.setTargetAtTime(this.mix.music, now, 0.02)
    this.sfxBus?.gain.setTargetAtTime(this.mix.sfx, now, 0.02)
    this.uiBus?.gain.setTargetAtTime(this.mix.ui, now, 0.02)
  }

  /** Backward-compatible master-volume setter. */
  setVolume(value: number): void {
    this.setMix({ master: value })
  }

  play(name: ToneName, pan = 0): void {
    if (!this.canPlaySfx()) return
    const context = this.context
    if (!context) return

    const now = context.currentTime
    const key = `tone:${name}`
    if (this.isCoolingDown(key, TONE_COOLDOWN_SECONDS[name] ?? 0, now)) return

    const familyDefinition: SampleFamily = {
      id: key,
      variants: SAMPLE_VARIANTS[name],
      fallback: name,
    }
    const bus: DestinationBus = UI_TONES.has(name) ? 'ui' : 'sfx'
    const played = this.playFamily(
      familyDefinition,
      pan,
      bus,
      'sfx',
      TONE_PRIORITY[name] ?? 35,
    )
    if (played) this.lastPlayedAt.set(key, now)
  }

  playDirectional(name: ToneName, horizontalDirection: number): void {
    this.play(name, horizontalDirection)
  }

  playWeaponFire(weaponId: WeaponAudioId, pan = 0): void {
    if (!this.canPlaySfx()) return
    const context = this.context
    if (!context) return
    const key = `weapon:${weaponId}:cooldown`
    const now = context.currentTime
    if (this.isCoolingDown(key, WEAPON_COOLDOWN_SECONDS[weaponId], now)) return

    let played = false
    for (const weaponFamily of WEAPON_FAMILIES[weaponId]) {
      played = this.playFamily(weaponFamily, pan, 'sfx', 'sfx', 40) || played
    }
    if (played) this.lastPlayedAt.set(key, now)
  }

  playEnemyAttack(kind: EnemyAttackKind, pan = 0): void {
    if (!this.canPlaySfx()) return
    const context = this.context
    if (!context) return
    const key = `enemy-attack:${kind}:cooldown`
    const now = context.currentTime
    const cooldown = kind === 'boss' ? 0.1 : kind === 'brute' ? 0.12 : 0.065
    if (this.isCoolingDown(key, cooldown, now)) return
    const played = this.playFamily(
      ENEMY_ATTACK_FAMILIES[kind],
      pan,
      'sfx',
      'sfx',
      kind === 'boss' ? 72 : kind === 'brute' ? 52 : 48,
    )
    if (played) this.lastPlayedAt.set(key, now)
  }

  /** Compatibility name retained for ranged call sites and older tests. */
  playEnemyFire(kind: EnemyFireKind, pan = 0): void {
    this.playEnemyAttack(kind, pan)
  }

  playImpact(event: ImpactAudioEvent): void {
    if (!this.canPlaySfx()) return
    const context = this.context
    if (!context) return
    const now = context.currentTime
    const mergeable = event.tier === 'normal' || event.tier === 'wall'
    if (mergeable && now - this.lastMergedImpactAt < IMPACT_MERGE_SECONDS)
      return

    let impactFamilies = IMPACT_FAMILIES[event.tier]
    if (
      event.source === 'player' &&
      event.weaponId === 'micro-missiles' &&
      (event.tier === 'normal' || event.tier === 'critical')
    ) {
      impactFamilies = [EXPLOSIVE_IMPACT]
    } else if (
      event.source === 'player' &&
      event.weaponId === 'arc-emitter' &&
      event.tier !== 'player-hit' &&
      event.tier !== 'wall'
    ) {
      impactFamilies =
        event.tier === 'normal' ? [ARC_IMPACT] : [ARC_IMPACT, ...impactFamilies]
    }

    let played = false
    for (const impactFamily of impactFamilies) {
      played =
        this.playFamily(
          impactFamily,
          event.pan ?? 0,
          'sfx',
          'impact',
          IMPACT_PRIORITY[event.tier],
        ) || played
    }
    if (played && mergeable) this.lastMergedImpactAt = now
  }

  playPlayerDeath(pan = 0): void {
    this.requestedMusicScene = 'none'
    this.fadeOutAllMusic(MUSIC_CROSSFADE_SECONDS)
    if (!this.canPlaySfx()) return

    this.playFamily(HEAVY_IMPACT, pan, 'sfx', 'sfx', 100)
    this.playFamily(EXPLOSIVE_IMPACT, pan, 'sfx', 'sfx', 100)
    this.playFamily(LOW_FREQUENCY_IMPACT, pan, 'sfx', 'sfx', 100)
    this.playShutdownSynth(pan)
  }

  /**
   * Briefly attenuates music and restores it on the audio timeline. Repeated
   * calls replace the previous envelope, so rapid hits cannot leave it muted.
   */
  duckMusic(decibels = -3, durationMs = 180): void {
    const context = this.context
    const duck = this.musicDuck
    if (!context || !duck || context.state !== 'running') return
    const now = context.currentTime
    const holdSeconds = Math.max(0, durationMs) / 1000
    const target = Math.max(SILENCE_GAIN, decibelsToGain(decibels))

    duck.gain.cancelScheduledValues(now)
    duck.gain.setValueAtTime(Math.max(SILENCE_GAIN, duck.gain.value), now)
    duck.gain.linearRampToValueAtTime(target, now + 0.02)
    duck.gain.setValueAtTime(target, now + 0.02 + holdSeconds)
    duck.gain.linearRampToValueAtTime(
      this.heldMusicDuckGain,
      now + 0.14 + holdSeconds,
    )
  }

  /** Holds a menu/gameplay-state duck until another state restores it. */
  setMusicDuck(decibels = 0, transitionMs = 250): void {
    this.heldMusicDuckGain = Math.max(SILENCE_GAIN, decibelsToGain(decibels))
    this.applyHeldMusicDuck(transitionMs)
  }

  private applyHeldMusicDuck(transitionMs: number): void {
    const context = this.context
    const duck = this.musicDuck
    if (!context || !duck || context.state !== 'running') return
    const now = context.currentTime
    const transitionSeconds = Math.max(0, transitionMs) / 1000
    duck.gain.cancelScheduledValues(now)
    duck.gain.setValueAtTime(Math.max(SILENCE_GAIN, duck.gain.value), now)
    duck.gain.linearRampToValueAtTime(
      this.heldMusicDuckGain,
      now + transitionSeconds,
    )
  }

  setMusicScene(scene: MusicScene): void {
    this.requestedMusicScene = scene
    if (scene === 'none') {
      this.fadeOutAllMusic(MUSIC_CROSSFADE_SECONDS)
      return
    }
    if (!this.context) return
    void this.preload().then(() => this.startMusicIfReady())
  }

  /** Backward-compatible gameplay-music entry point. */
  startMusic(): void {
    this.setMusicScene('combat')
  }

  /** Backward-compatible music stop with the polished 0.9 second tail. */
  stopMusic(): void {
    this.setMusicScene('none')
  }

  private canPlaySfx(): boolean {
    if (this.context && this.context.state !== 'running') this.armResumeRetry()
    return Boolean(
      this.context &&
      this.sfxBus &&
      this.uiBus &&
      this.context.state === 'running' &&
      this.mix.master > 0 &&
      (this.mix.sfx > 0 || this.mix.ui > 0),
    )
  }

  private isCoolingDown(key: string, cooldown: number, now: number): boolean {
    if (cooldown <= 0) return false
    const lastPlayedAt = this.lastPlayedAt.get(key)
    return lastPlayedAt !== undefined && now - lastPlayedAt < cooldown
  }

  private playFamily(
    sampleFamily: SampleFamily,
    pan: number,
    bus: DestinationBus,
    className: VoiceClass,
    priority: number,
  ): boolean {
    return (
      this.playSampleFamily(sampleFamily, pan, bus, className, priority) ||
      this.playSynthesized(sampleFamily.fallback, pan, bus, className, priority)
    )
  }

  private playSampleFamily(
    sampleFamily: SampleFamily,
    pan: number,
    bus: DestinationBus,
    className: VoiceClass,
    priority: number,
  ): boolean {
    const context = this.context
    if (!context || !this.ensureVoiceSlot(className, priority)) return false

    const familyVariants = sampleFamily.variants
    const startIndex = this.variationIndices.get(sampleFamily.id) ?? 0
    this.variationIndices.set(
      sampleFamily.id,
      (startIndex + 1) % familyVariants.length,
    )

    for (let offset = 0; offset < familyVariants.length; offset += 1) {
      const variant =
        familyVariants[(startIndex + offset) % familyVariants.length]
      const buffer = this.buffers.get(variant.path)
      if (!buffer) continue

      let source: AudioBufferSourceNode | null = null
      let gain: GainNode | null = null
      let panner: StereoPannerNode | null = null
      try {
        source = context.createBufferSource()
        gain = context.createGain()
        source.buffer = buffer
        source.playbackRate.setValueAtTime(
          variant.playbackRate ?? 1,
          context.currentTime,
        )
        gain.gain.setValueAtTime(variant.gain, context.currentTime)
        source.connect(gain)
        panner = this.connectPanned(gain, pan, bus)
        source.start(context.currentTime)
        this.registerVoice(source, className, priority, () => {
          source?.disconnect()
          gain?.disconnect()
          panner?.disconnect()
        })
        return true
      } catch {
        source?.disconnect()
        gain?.disconnect()
        panner?.disconnect()
      }
    }
    return false
  }

  private playSynthesized(
    name: ToneName,
    pan: number,
    bus: DestinationBus,
    className: VoiceClass,
    priority: number,
  ): boolean {
    const context = this.context
    if (!context || !this.ensureVoiceSlot(className, priority)) return false

    const tone = TONES[name]
    const now = context.currentTime
    let oscillator: OscillatorNode | null = null
    let gain: GainNode | null = null
    let panner: StereoPannerNode | null = null
    try {
      oscillator = context.createOscillator()
      gain = context.createGain()
      oscillator.type = tone.type
      oscillator.frequency.setValueAtTime(tone.frequency, now)
      oscillator.frequency.exponentialRampToValueAtTime(
        Math.max(45, tone.frequency * 0.55),
        now + tone.duration,
      )
      gain.gain.setValueAtTime(SILENCE_GAIN, now)
      gain.gain.exponentialRampToValueAtTime(0.18, now + 0.008)
      gain.gain.exponentialRampToValueAtTime(SILENCE_GAIN, now + tone.duration)
      oscillator.connect(gain)
      panner = this.connectPanned(gain, pan, bus)
      oscillator.start(now)
      oscillator.stop(now + tone.duration + 0.02)
      this.registerVoice(oscillator, className, priority, () => {
        oscillator?.disconnect()
        gain?.disconnect()
        panner?.disconnect()
      })
      return true
    } catch {
      oscillator?.disconnect()
      gain?.disconnect()
      panner?.disconnect()
      return false
    }
  }

  private playShutdownSynth(pan: number): void {
    const context = this.context
    if (!context || !this.ensureVoiceSlot('sfx', 100)) return
    const now = context.currentTime
    let oscillator: OscillatorNode | null = null
    let gain: GainNode | null = null
    let panner: StereoPannerNode | null = null
    try {
      oscillator = context.createOscillator()
      gain = context.createGain()
      oscillator.type = 'sawtooth'
      oscillator.frequency.setValueAtTime(310, now)
      oscillator.frequency.exponentialRampToValueAtTime(45, now + 0.72)
      gain.gain.setValueAtTime(SILENCE_GAIN, now)
      gain.gain.exponentialRampToValueAtTime(0.2, now + 0.015)
      gain.gain.exponentialRampToValueAtTime(SILENCE_GAIN, now + 0.75)
      oscillator.connect(gain)
      panner = this.connectPanned(gain, pan, 'sfx')
      oscillator.start(now)
      oscillator.stop(now + 0.77)
      this.registerVoice(oscillator, 'sfx', 100, () => {
        oscillator?.disconnect()
        gain?.disconnect()
        panner?.disconnect()
      })
    } catch {
      oscillator?.disconnect()
      gain?.disconnect()
      panner?.disconnect()
    }
  }

  private connectPanned(
    node: AudioNode,
    pan: number,
    destinationBus: DestinationBus,
  ): StereoPannerNode | null {
    const context = this.context
    const destination = destinationBus === 'ui' ? this.uiBus : this.sfxBus
    if (!context || !destination) return null

    try {
      const panner = context.createStereoPanner()
      panner.pan.setValueAtTime(clampPan(pan), context.currentTime)
      node.connect(panner)
      panner.connect(destination)
      return panner
    } catch {
      node.connect(destination)
      return null
    }
  }

  private ensureVoiceSlot(className: VoiceClass, priority: number): boolean {
    if (className === 'impact') {
      const impactVoices = [...this.activeVoices].filter(
        (voice) => voice.className === 'impact',
      )
      if (impactVoices.length >= MAX_IMPACT_VOICES) {
        if (!this.evictLowerPriority(impactVoices, priority)) return false
      }
    }
    if (this.activeVoices.size >= MAX_SFX_VOICES) {
      if (!this.evictLowerPriority([...this.activeVoices], priority))
        return false
    }
    return true
  }

  private evictLowerPriority(
    candidates: readonly ActiveVoice[],
    incomingPriority: number,
  ): boolean {
    const lowest = candidates.reduce<ActiveVoice | null>(
      (candidate, voice) =>
        !candidate || voice.priority < candidate.priority ? voice : candidate,
      null,
    )
    if (!lowest || lowest.priority >= incomingPriority) return false
    lowest.stop()
    return true
  }

  private registerVoice(
    source: AudioScheduledSourceNode,
    className: VoiceClass,
    priority: number,
    disconnect: () => void,
  ): void {
    let finished = false
    const finish = (stopSource: boolean) => {
      if (finished) return
      finished = true
      this.activeVoices.delete(voice)
      if (stopSource) {
        try {
          source.stop(this.context?.currentTime ?? 0)
        } catch {
          // A naturally ended source can race an incoming priority eviction.
        }
      }
      disconnect()
    }
    const voice: ActiveVoice = {
      className,
      priority,
      stop: () => finish(true),
    }
    this.activeVoices.add(voice)
    source.onended = () => finish(false)
  }

  private startMusicIfReady(): void {
    const context = this.context
    const destination = this.musicDuck
    const scene = this.requestedMusicScene
    if (
      scene === 'none' ||
      !context ||
      !destination ||
      context.state !== 'running' ||
      (this.currentMusic?.scene === scene && !this.currentMusic.stopping)
    ) {
      return
    }

    const buffer = this.buffers.get(MUSIC_PATHS[scene])
    if (!buffer) return

    let source: AudioBufferSourceNode | null = null
    let gain: GainNode | null = null
    try {
      source = context.createBufferSource()
      gain = context.createGain()
      source.buffer = buffer
      source.loop = true
      gain.gain.setValueAtTime(SILENCE_GAIN, context.currentTime)
      source.connect(gain)
      gain.connect(destination)
      const playback: MusicPlayback = {
        scene,
        source,
        gain,
        stopping: false,
      }
      this.musicPlaybacks.add(playback)
      const previous = this.currentMusic
      this.currentMusic = playback
      source.onended = () => {
        source?.disconnect()
        gain?.disconnect()
        this.musicPlaybacks.delete(playback)
        if (this.currentMusic === playback) this.currentMusic = null
      }
      source.start(context.currentTime)
      this.scheduleEqualPowerFade(gain.gain, true, context.currentTime)
      if (previous) this.fadeOutMusic(previous, MUSIC_CROSSFADE_SECONDS)
    } catch {
      source?.disconnect()
      gain?.disconnect()
    }
  }

  private scheduleEqualPowerFade(
    parameter: AudioParam,
    fadeIn: boolean,
    now: number,
    maximumGain = MUSIC_PROGRAM_GAIN,
  ): void {
    parameter.cancelScheduledValues(now)
    try {
      parameter.setValueCurveAtTime(
        equalPowerCurve(fadeIn, maximumGain),
        now,
        MUSIC_CROSSFADE_SECONDS,
      )
    } catch {
      parameter.setValueAtTime(fadeIn ? SILENCE_GAIN : maximumGain, now)
      parameter.linearRampToValueAtTime(
        fadeIn ? maximumGain : SILENCE_GAIN,
        now + MUSIC_CROSSFADE_SECONDS,
      )
    }
  }

  private fadeOutAllMusic(duration: number): void {
    this.currentMusic = null
    for (const playback of this.musicPlaybacks) {
      this.fadeOutMusic(playback, duration)
    }
  }

  private fadeOutMusic(playback: MusicPlayback, duration: number): void {
    const context = this.context
    if (!context || playback.stopping) return
    playback.stopping = true
    const now = context.currentTime
    try {
      playback.gain.gain.cancelScheduledValues(now)
      playback.gain.gain.setValueAtTime(
        Math.max(SILENCE_GAIN, playback.gain.gain.value),
        now,
      )
      if (duration === MUSIC_CROSSFADE_SECONDS) {
        this.scheduleEqualPowerFade(
          playback.gain.gain,
          false,
          now,
          Math.max(SILENCE_GAIN, playback.gain.gain.value),
        )
      } else {
        playback.gain.gain.linearRampToValueAtTime(SILENCE_GAIN, now + duration)
      }
      playback.source.stop(now + duration + 0.02)
    } catch {
      playback.source.disconnect()
      playback.gain.disconnect()
      this.musicPlaybacks.delete(playback)
    }
  }

  private armResumeRetry(): void {
    if (this.resumeRetryArmed || typeof window === 'undefined') return
    this.resumeRetryArmed = true
    window.addEventListener('pointerdown', this.retryUnlock, {
      capture: true,
      once: true,
    })
    window.addEventListener('keydown', this.retryUnlock, {
      capture: true,
      once: true,
    })
  }

  private disarmResumeRetry(): void {
    if (!this.resumeRetryArmed || typeof window === 'undefined') return
    this.resumeRetryArmed = false
    window.removeEventListener('pointerdown', this.retryUnlock, true)
    window.removeEventListener('keydown', this.retryUnlock, true)
  }
}

export const audioEngine = new AudioEngine()
