export type GamePhase =
  | 'title'
  | 'booting'
  | 'lobby'
  | 'expedition-loading'
  | 'playing'
  | 'paused'
  | 'reward'
  | 'defeat'
  | 'error'

export type RuntimeStats = PlayerStats

export interface ProjectileSpawn {
  id: string
  position: [number, number, number]
  direction: [number, number, number]
  speed: number
  damage: number
  color: string
  radius?: number
  kind?: 'magic' | 'liberation'
  /** Enemy targeted by a Veil Breaker's gaze-release bolt. */
  targetEnemyId?: string
  /** Telegraph delay during which a support projectile remains at its origin. */
  activationDelayMs?: number
}

export type EffectKind =
  | 'slash'
  | 'hit'
  | 'hurt'
  | 'burst'
  | 'dash'
  | 'telegraph'
  | 'trail'
  | 'death'
  /** Red pigment pulled from a hostile figurine when the gaze freezes it. */
  | 'drain'
  /** Gaze takes hold: a ring closing on the enemy plus a rising light column. */
  | 'seal'
  /** The veil tears: radial shards thrown outward from a white core. */
  | 'shatter'

export interface EffectSpawn {
  id: string
  kind: EffectKind
  position: [number, number, number]
  direction?: [number, number, number]
  color: string
  durationMs?: number
  length?: number
  width?: number
  variant?: 'arc' | 'lane' | 'rune' | 'sigil' | 'drain'
  label?: string
}

export interface ThreatWarning {
  id: string
  angleDeg: number
  kind: 'melee' | 'ranged' | 'boss'
  durationMs: number
}

export interface PlayerHitFeedback {
  id: string
  damage: number
  /** Normalized world-space direction from the player toward the attacker. */
  direction: [number, number, number]
}

export interface GameImpactFeedbackEvent extends ImpactFeedbackEvent {
  /** Death owns a dedicated layered sting, so its base hurt cue is skipped. */
  readonly playAudio?: boolean
  readonly cameraTrauma?: number
  readonly cameraKick?: number
  readonly hitstopSeconds?: number
  readonly rumble?: Readonly<{ intensity: number; durationMs: number }>
}

export interface StartGeneratedRunOptions {
  readonly loadout?: EquipmentLoadout
  readonly permanentProfile?: PermanentStatProfile
  /** Content unlocked for this run; omitted keeps legacy full-catalog runs. */
  readonly allowedWeaponIds?: readonly string[]
  /** Content unlocked for this run; omitted keeps legacy full-catalog runs. */
  readonly allowedPassiveIds?: readonly string[]
  /** Auto-firing weapon selected at deployment. */
  readonly startingWeaponId?: RangedWeaponId
  /** Used by legacy/debug entry points. Normal expeditions wait for scene warmup. */
  readonly startImmediately?: boolean
}

interface SettingsState {
  masterVolume: number
  musicVolume: number
  sfxVolume: number
  visionAssist: number
  reducedMotion: boolean
  gamepadVibration: boolean
}

export interface GameState {
  phase: GamePhase
  errorMessage: string | null
  seed: string
  runId: number
  roomIndex: number
  roomIds: string[]
  generatedRun: GeneratedRun | null
  currentNodeId: string | null
  visitedNodeIds: string[]
  availableNodeIds: string[]
  mode: GameMode
  dailyDateKey: string | null
  difficulty: DifficultyRank
  health: number
  score: number
  aliveEnemies: number
  /** True once the player has reached the current sector's exit gate. */
  roomEscaped: boolean
  /**
   * Seconds survived in this run. There are no sectors any more — this one
   * number is the difficulty, the score, and the leaderboard entry.
   */
  runElapsedSeconds: number
  /** Lifetime experience this run. Level is derived from it, never stored. */
  experience: number
  /** Level-up choices owed after collecting one or more XP cores. */
  pendingLevelUps: number
  runBuild: RunBuildState
  allowedWeaponIds: WeaponId[]
  allowedPassiveIds: PassiveId[]
  levelUpOffers: LevelUpOffer[]
  /** Shared across the run; spending one redraws all three cards. */
  levelUpRerolls: number
  levelUpOfferRoll: number
  weaponCooldowns: Partial<Record<WeaponId, number>>
  /** 0 immediately after dashing, 1 once the mobility burst is ready. */
  dashCooldownProgress: number
  weaponRunStats: Record<WeaponId, { damage: number; kills: number }>
  runArmor: number
  healthRegenPerSecond: number
  pickupRadius: number
  /** Bosses felled this run; they carry most of the payout weight. */
  bossKills: number
  observedEnemies: number
  defeatedEnemies: number
  lastInputDevice: InputDevice
  stats: RuntimeStats
  statCaps: PlayerStatCaps
  permanentProfile: PermanentStatProfile
  loadout: EquipmentLoadout
  projectiles: ProjectileSpawn[]
  effects: EffectSpawn[]
  threats: ThreatWarning[]
  lastPlayerHit: PlayerHitFeedback | null
  settings: SettingsState
  beginBoot: () => void
  enterLobby: () => void
  beginPlaying: () => void
  failLoading: (message: string) => void
  startGeneratedRun: (
    run: GeneratedRun,
    options?: StartGeneratedRunOptions,
  ) => void
  startRun: (
    seed: string,
    roomIds: string[],
    loadout: EquipmentLoadout,
    difficulty?: DifficultyRank,
    permanentProfile?: PermanentStatProfile,
  ) => void
  retryCurrentRoom: () => void
  returnToTitle: () => void
  togglePause: () => void
  setRoomPopulation: (count: number) => void
  setRunElapsedSeconds: (seconds: number) => void
  gainExperience: (amount: number) => void
  chooseLevelUpOffer: (offerId: string) => void
  rerollLevelUpOffers: () => void
  setWeaponCooldown: (weaponId: WeaponId, progress: number) => void
  setDashCooldownProgress: (progress: number) => void
  recordWeaponDamage: (
    weaponId: WeaponId,
    damage: number,
    defeated?: boolean,
  ) => void
  adjustObservedEnemies: (delta: number) => void
  defeatEnemy: (score: number, kind?: KillKind) => void
  /** Marks the current sector escaped; the scene layer resolves the exit. */
  escapeRoom: () => void
  awardScore: (score: number) => void
  damagePlayer: (
    amount: number,
    sourcePosition?: readonly [number, number, number],
  ) => void
  healPlayer: (amount: number) => void
  spawnProjectile: (projectile: ProjectileSpawn) => void
  removeProjectile: (id: string) => void
  spawnEffect: (effect: EffectSpawn) => void
  publishImpact: (event: GameImpactFeedbackEvent) => void
  setThreat: (threat: ThreatWarning) => void
  clearThreat: (id: string) => void
  setMasterVolume: (value: number) => void
  setMusicVolume: (value: number) => void
  setSfxVolume: (value: number) => void
  setVisionAssist: (value: number) => void
  setReducedMotion: (value: boolean) => void
  setGamepadVibration: (value: boolean) => void
  setLastInputDevice: (device: InputDevice) => void
}

/** Recent spawns retained for the debug bridge only; the renderer owns lifetime. */
const RECENT_EFFECT_LIMIT = 24

const DEFAULT_PERMANENT_PROFILE = derivePermanentStatProfile(
  EMPTY_PERMANENT_STAT_LEVELS,
)
const DEFAULT_STATS: RuntimeStats = deriveLoadoutStats(DEFAULT_LOADOUT)
const WEAPON_STAT_IDS = [
  'pulse-carbine',
  'scatter-cannon',
  'micro-missiles',
  'rail-lance',
  'arc-emitter',
  'orbit-drone',
] as const satisfies readonly WeaponId[]

function canonicalAllowedWeaponIds(
  requestedIds: readonly string[] | undefined,
): WeaponId[] {
  const requested = new Set(requestedIds ?? WEAPON_IDS)
  return WEAPON_IDS.filter((id) => requested.has(id))
}

function canonicalAllowedPassiveIds(
  requestedIds: readonly string[] | undefined,
): PassiveId[] {
  const requested = new Set(requestedIds ?? PASSIVE_IDS)
  return PASSIVE_IDS.filter((id) => requested.has(id))
}

function emptyWeaponRunStats(): GameState['weaponRunStats'] {
  return Object.fromEntries(
    WEAPON_STAT_IDS.map((id) => [id, { damage: 0, kills: 0 }]),
  ) as GameState['weaponRunStats']
}

/**
 * Folds run passives onto the loadout baseline. Exported so the safety floors
 * — especially the optic angle ceiling, which vision.ts throws above — can be
 * tested without driving a whole run.
 */
export function statsWithRunPassives(
  base: RuntimeStats,
  build: RunBuildState,
): Pick<
  GameState,
  'stats' | 'runArmor' | 'healthRegenPerSecond' | 'pickupRadius'
> {
  const player = deriveRunModifiers(build.passives).player
  return {
    stats: {
      ...base,
      maxHealth: Math.max(1, base.maxHealth + player.maxHealthAdd),
      moveSpeed: Math.max(4, base.moveSpeed * player.moveSpeedMultiplier),
      dodgeCooldownMs: Math.max(
        120,
        base.dodgeCooldownMs * player.dodgeCooldownMultiplier,
      ),
      visionRange: Math.max(5, base.visionRange * player.opticRangeMultiplier),
      // The upper bound is not cosmetic: assertVisionConfig throws above 360,
      // and it runs per enemy per frame, so one stacked passive would kill
      // the scene rather than just look wrong.
      visionFovDeg: Math.min(
        360,
        Math.max(20, base.visionFovDeg + player.opticAngleAddDeg),
      ),
    },
    runArmor: Math.max(0, Math.floor(player.armorAdd)),
    healthRegenPerSecond: Math.max(0, player.healthRegenPerSecondAdd),
    pickupRadius: Math.max(0.8, 4.2 * player.pickupRadiusMultiplier),
  }
}
function nextId(prefix: string): string {
  return `${prefix}-${Math.floor(performance.now())}-${Math.random().toString(36).slice(2, 7)}`
}

/**
 * The one publishing boundary for every rendered effect. It guarantees that
 * the imperative renderer queue and the bounded debug history see the exact
 * same immutable spawn instead of drifting into separate code paths.
 */
function publishEffect(effect: EffectSpawn): EffectSpawn {
  const spawned = { ...effect, id: effect.id || nextId('fx') }
  enqueueVfx(spawned)
  return spawned
}

function clonePermanentProfile(
  profile: PermanentStatProfile = DEFAULT_PERMANENT_PROFILE,
): PermanentStatProfile {
  return { stats: { ...profile.stats }, caps: { ...profile.caps } }
}

function clearsEncounter() {
  // Pending spawns belong to the encounter that just ended.
  resetVfxQueue()
  resetHitstop()
  return {
    aliveEnemies: 0,
    roomEscaped: false,
    runElapsedSeconds: 0,
    experience: 0,
    pendingLevelUps: 0,
    levelUpOffers: [] as LevelUpOffer[],
    levelUpRerolls: 2,
    levelUpOfferRoll: 0,
    weaponCooldowns: {} as Partial<Record<WeaponId, number>>,
    dashCooldownProgress: 1,
    weaponRunStats: emptyWeaponRunStats(),
    bossKills: 0,
    observedEnemies: 0,
    projectiles: [] as ProjectileSpawn[],
    effects: [] as EffectSpawn[],
    threats: [] as ThreatWarning[],
    lastPlayerHit: null,
  }
}

function prepareRunStats(
  loadout: EquipmentLoadout,
  permanentProfile: PermanentStatProfile,
): RuntimeStats {
  // Deliberate ordering: base -> permanent profile -> equipped items. Runes are
  // applied by chooseRune afterwards with these permanently raised caps.
  return deriveLoadoutStats(
    loadout,
    permanentProfile.stats,
    permanentProfile.caps,
  )
}

function resetPlayerToRoomSpawn(): void {
  runtime.playerPosition.set(0, 0.8, 5.5)
  runtime.enemies.clear()
  runtime.shards.length = 0
  runtime.playerInvulnerableUntil = runtime.elapsed
}

export const useGameStore = create<GameState>((set, get) => ({
  phase: 'title',
  errorMessage: null,
  seed: '',
  runId: 0,
  roomIndex: 0,
  roomIds: [],
  generatedRun: null,
  currentNodeId: null,
  visitedNodeIds: [],
  availableNodeIds: [],
  mode: 'standard',
  dailyDateKey: null,
  difficulty: 1,
  health: DEFAULT_STATS.maxHealth,
  score: 0,
  aliveEnemies: 0,
  roomEscaped: false,
  runElapsedSeconds: 0,
  experience: 0,
  pendingLevelUps: 0,
  runBuild: createInitialRunBuild(),
  allowedWeaponIds: [...WEAPON_IDS],
  allowedPassiveIds: [...PASSIVE_IDS],
  levelUpOffers: [],
  levelUpRerolls: 2,
  levelUpOfferRoll: 0,
  weaponCooldowns: {},
  dashCooldownProgress: 1,
  weaponRunStats: emptyWeaponRunStats(),
  runArmor: 0,
  healthRegenPerSecond: 0,
  pickupRadius: 4.2,
  bossKills: 0,
  observedEnemies: 0,
  defeatedEnemies: 0,
  lastInputDevice: 'keyboard-mouse',
  stats: DEFAULT_STATS,
  statCaps: { ...PLAYER_STAT_CAPS },
  permanentProfile: clonePermanentProfile(),
  loadout: { ...DEFAULT_LOADOUT },
  projectiles: [],
  effects: [],
  threats: [],
  lastPlayerHit: null,
  settings: {
    masterVolume: 0.55,
    musicVolume: 0.7,
    sfxVolume: 0.8,
    visionAssist: 0.75,
    reducedMotion: false,
    gamepadVibration: true,
  },
  beginBoot: () => {
    const phase = get().phase
    if (phase === 'title' || phase === 'lobby' || phase === 'error') {
      audioEngine.setMusicScene('menu')
      set({ phase: 'booting', errorMessage: null })
    }
  },
  enterLobby: () => {
    audioEngine.setMusicScene('menu')
    audioEngine.setMusicDuck(0, 180)
    resetRuntime()
    set({
      phase: 'lobby',
      errorMessage: null,
      generatedRun: null,
      currentNodeId: null,
      visitedNodeIds: [],
      availableNodeIds: [],
      roomIndex: 0,
      roomIds: [],
      mode: 'standard',
      dailyDateKey: null,
      allowedWeaponIds: [...WEAPON_IDS],
      allowedPassiveIds: [...PASSIVE_IDS],
      ...clearsEncounter(),
    })
  },
  beginPlaying: () => {
    if (get().phase === 'expedition-loading') set({ phase: 'playing' })
  },
  failLoading: (message) => {
    audioEngine.setMusicScene('none')
    set({
      phase: 'error',
      errorMessage: message.trim() || 'STILLSEEN failed to load.',
    })
  },
  startGeneratedRun: (run, options = {}) => {
    const permanentProfile = clonePermanentProfile(options.permanentProfile)
    const loadout = { ...(options.loadout ?? DEFAULT_LOADOUT) }
    const initialStats = prepareRunStats(loadout, permanentProfile)
    const allowedWeaponIds = canonicalAllowedWeaponIds(options.allowedWeaponIds)
    const allowedPassiveIds = canonicalAllowedPassiveIds(
      options.allowedPassiveIds,
    )
    const startingWeaponId = options.startingWeaponId ?? 'pulse-carbine'
    const initialBuild = createInitialRunBuild(startingWeaponId)
    const startNode = getRoomNode(run, run.startNodeId)
    audioEngine.setMusicScene('combat')
    audioEngine.setMusicDuck(0, 180)
    resetRuntime()
    set((state) => ({
      phase: options.startImmediately ? 'playing' : 'expedition-loading',
      errorMessage: null,
      seed: run.seed,
      runId: state.runId + 1,
      roomIndex: startNode.depth - 1,
      roomIds: run.rooms.map((room) => room.templateId),
      generatedRun: run,
      currentNodeId: run.startNodeId,
      visitedNodeIds: [run.startNodeId],
      availableNodeIds: [],
      mode: run.mode,
      dailyDateKey: run.dailyDateKey,
      difficulty: run.difficulty,
      health: initialStats.maxHealth,
      score: 0,
      defeatedEnemies: 0,
      runBuild: initialBuild,
      allowedWeaponIds,
      allowedPassiveIds,
      ...statsWithRunPassives(initialStats, initialBuild),
      statCaps: { ...permanentProfile.caps },
      permanentProfile,
      loadout,
      ...clearsEncounter(),
    }))
  },
  startRun: (seed, roomIds, loadout, difficulty = 1, permanentProfile) => {
    const run = createRun(seed, difficulty)
    get().startGeneratedRun(run, {
      loadout,
      permanentProfile,
      startImmediately: true,
    })
    // Preserve the caller-provided legacy list even though graph navigation is
    // now driven by generatedRun/currentNodeId.
    set({ roomIds: [...roomIds] })
  },
  retryCurrentRoom: () => {
    const state = get()
    if (state.phase !== 'defeat' || state.currentNodeId === null) return
    audioEngine.setMusicScene('combat')
    audioEngine.setMusicDuck(0, 180)
    resetRuntime()
    resetPlayerToRoomSpawn()
    set({
      phase: 'playing',
      runId: state.runId + 1,
      health: state.stats.maxHealth,
      score: 0,
      defeatedEnemies: 0,
      runBuild: createInitialRunBuild(
        state.runBuild.weaponSlots[0]?.weaponId ?? 'pulse-carbine',
      ),
      ...clearsEncounter(),
    })
  },
  returnToTitle: () => {
    audioEngine.setMusicScene('menu')
    audioEngine.setMusicDuck(0, 180)
    resetRuntime()
    set({
      phase: 'title',
      errorMessage: null,
      roomIndex: 0,
      roomIds: [],
      generatedRun: null,
      currentNodeId: null,
      visitedNodeIds: [],
      availableNodeIds: [],
      mode: 'standard',
      dailyDateKey: null,
      allowedWeaponIds: [...WEAPON_IDS],
      allowedPassiveIds: [...PASSIVE_IDS],
      ...clearsEncounter(),
    })
  },
  togglePause: () => {
    const state = get()
    if (state.phase === 'playing') {
      audioEngine.setMusicDuck(-4, 250)
      set({ phase: 'paused' })
    } else if (state.phase === 'paused') {
      audioEngine.setMusicDuck(0, 180)
      set({ phase: 'playing' })
    }
  },
  setRoomPopulation: (count) =>
    set({ aliveEnemies: Math.max(0, Math.floor(count)) }),

  setRunElapsedSeconds: (seconds) =>
    set({
      runElapsedSeconds: Number.isFinite(seconds) ? Math.max(0, seconds) : 0,
    }),
  gainExperience: (amount) => {
    if (!Number.isFinite(amount) || amount <= 0) return
    const previousPhase = get().phase
    set((state) => {
      const experienceMultiplier = deriveRunModifiers(state.runBuild.passives)
        .player.experienceGainMultiplier
      const gained = Math.max(1, Math.round(amount * experienceMultiplier))
      const experience = state.experience + gained
      const crossed = Math.max(
        0,
        experienceLevel(experience) - experienceLevel(state.experience),
      )
      const pendingLevelUps = state.pendingLevelUps + crossed
      const shouldOpen =
        crossed > 0 &&
        state.levelUpOffers.length === 0 &&
        state.phase === 'playing'
      const offerLevel = experienceLevel(experience) - pendingLevelUps + 1
      return {
        experience,
        pendingLevelUps,
        phase: shouldOpen ? 'reward' : state.phase,
        levelUpOffers: shouldOpen
          ? [
              ...createLevelUpOffers(
                state.runBuild,
                state.seed,
                offerLevel,
                {
                  allowedWeaponIds: state.allowedWeaponIds,
                  allowedPassiveIds: state.allowedPassiveIds,
                },
                state.levelUpOfferRoll,
              ),
            ]
          : state.levelUpOffers,
      }
    })
    if (previousPhase === 'playing' && get().phase === 'reward') {
      audioEngine.setMusicDuck(-4, 250)
    }
  },
  chooseLevelUpOffer: (offerId) => {
    const state = get()
    if (state.phase !== 'reward') return
    const offer = state.levelUpOffers.find(
      (candidate) => candidate.id === offerId,
    )
    if (!offer) return
    const runBuild = applyLevelUpOffer(state.runBuild, offer)
    if (runBuild === state.runBuild) return
    const pendingLevelUps = Math.max(0, state.pendingLevelUps - 1)
    const derived = statsWithRunPassives(
      prepareRunStats(state.loadout, state.permanentProfile),
      runBuild,
    )
    const maxHealthGain = Math.max(
      0,
      derived.stats.maxHealth - state.stats.maxHealth,
    )
    const nextOfferLevel =
      experienceLevel(state.experience) - pendingLevelUps + 1
    set({
      runBuild,
      pendingLevelUps,
      ...derived,
      health: Math.min(
        derived.stats.maxHealth,
        Math.max(1, state.health + maxHealthGain),
      ),
      phase: pendingLevelUps > 0 ? 'reward' : 'playing',
      levelUpOffers:
        pendingLevelUps > 0
          ? [
              ...createLevelUpOffers(
                runBuild,
                state.seed,
                nextOfferLevel,
                {
                  allowedWeaponIds: state.allowedWeaponIds,
                  allowedPassiveIds: state.allowedPassiveIds,
                },
                state.levelUpOfferRoll,
              ),
            ]
          : [],
    })
    if (pendingLevelUps === 0) audioEngine.setMusicDuck(0, 180)
    audioEngine.play('reward')
  },
  rerollLevelUpOffers: () => {
    const state = get()
    if (
      state.phase !== 'reward' ||
      state.levelUpOffers.length !== 3 ||
      state.levelUpRerolls <= 0
    )
      return
    const levelUpOfferRoll = state.levelUpOfferRoll + 1
    const offerLevel =
      experienceLevel(state.experience) - state.pendingLevelUps + 1
    set({
      levelUpRerolls: state.levelUpRerolls - 1,
      levelUpOfferRoll,
      levelUpOffers: [
        ...createLevelUpOffers(
          state.runBuild,
          state.seed,
          offerLevel,
          {
            allowedWeaponIds: state.allowedWeaponIds,
            allowedPassiveIds: state.allowedPassiveIds,
          },
          levelUpOfferRoll,
        ),
      ],
    })
    audioEngine.play('room-start')
  },
  setWeaponCooldown: (weaponId, progress) =>
    set((state) => ({
      weaponCooldowns: {
        ...state.weaponCooldowns,
        [weaponId]: Math.max(0, Math.min(1, progress)),
      },
    })),
  setDashCooldownProgress: (progress) =>
    set({
      dashCooldownProgress: Math.max(0, Math.min(1, progress)),
    }),
  recordWeaponDamage: (weaponId, damage, defeated = false) => {
    if (!Number.isFinite(damage) || damage <= 0) return
    set((state) => ({
      weaponRunStats: {
        ...state.weaponRunStats,
        [weaponId]: {
          damage: state.weaponRunStats[weaponId].damage + damage,
          kills: state.weaponRunStats[weaponId].kills + (defeated ? 1 : 0),
        },
      },
    }))
  },
  adjustObservedEnemies: (delta) =>
    set((state) => ({
      observedEnemies: Math.max(0, state.observedEnemies + delta),
    })),
  escapeRoom: () => {
    const state = get()
    if (state.phase !== 'playing' || state.roomEscaped) return
    // The exit is a reward for clearing, not a way around the fight. Guarding
    // here rather than in the scene means the debug bridge obeys the same
    // rule the player does.
    if (state.aliveEnemies > 0) return
    set({ roomEscaped: true })
  },
  defeatEnemy: (enemyScore, kind = 'normal') => {
    const state = get()
    const remaining = Math.max(0, state.aliveEnemies - 1)
    const bossDefeated = kind === 'boss'
    const bossHeal = bossDefeated ? state.stats.maxHealth * 0.2 : 0
    set({
      aliveEnemies: remaining,
      defeatedEnemies: state.defeatedEnemies + 1,
      score: state.score + enemyScore,
      bossKills: state.bossKills + (bossDefeated ? 1 : 0),
      health: bossDefeated
        ? Math.min(state.stats.maxHealth, state.health + bossHeal)
        : state.health,
      levelUpRerolls: bossDefeated
        ? Math.min(3, state.levelUpRerolls + 1)
        : state.levelUpRerolls,
    })
  },
  awardScore: (bonus) => {
    if (!Number.isFinite(bonus) || bonus <= 0) return
    set((state) => ({ score: state.score + Math.floor(bonus) }))
  },
  damagePlayer: (amount, sourcePosition) => {
    const state = get()
    if (
      state.phase !== 'playing' ||
      runtime.elapsed < runtime.playerInvulnerableUntil
    )
      return
    const armoredDamage = Math.max(1, amount - state.runArmor)
    const appliedDamage = Math.max(0, Math.min(state.health, armoredDamage))
    if (appliedDamage <= 0) return
    const health = state.health - appliedDamage
    const hitDirection = sourcePosition
      ? runtime.playerHitDirection.set(
          sourcePosition[0] - runtime.playerPosition.x,
          0,
          sourcePosition[2] - runtime.playerPosition.z,
        )
      : runtime.playerHitDirection.copy(runtime.playerFacing).negate().setY(0)
    if (hitDirection.lengthSq() < 0.0001) hitDirection.set(0, 0, 1)
    hitDirection.normalize()
    const direction: [number, number, number] = [
      hitDirection.x,
      0,
      hitDirection.z,
    ]
    const hitId = nextId('player-hit')
    runtime.playerInvulnerableUntil = Math.max(
      runtime.playerInvulnerableUntil,
      runtime.elapsed + 0.25,
    )
    set({
      health,
      phase: health === 0 ? 'defeat' : state.phase,
      lastPlayerHit: { id: hitId, damage: appliedDamage, direction },
    })
    get().publishImpact({
      id: `${hitId}-effect`,
      tier: 'player-hit',
      position: [runtime.playerPosition.x, 0.82, runtime.playerPosition.z],
      direction,
      source: 'enemy',
      color: '#ffffff',
      cameraTrauma: 0.92,
      cameraKick: 1,
      hitstopSeconds: 0.06,
      playAudio: health > 0,
      rumble: {
        intensity: health === 0 ? 1 : 0.7,
        durationMs: health === 0 ? 220 : 120,
      },
    })
    if (health === 0) audioEngine.playPlayerDeath(direction[0])
    else audioEngine.duckMusic(-3, 180)
  },
  healPlayer: (amount) =>
    set((state) => ({
      health: Math.min(
        state.stats.maxHealth,
        state.health + Math.max(0, amount),
      ),
    })),
  spawnProjectile: (projectile) =>
    set((state) => ({ projectiles: [...state.projectiles, projectile] })),
  removeProjectile: (id) =>
    set((state) => ({
      projectiles: state.projectiles.filter((item) => item.id !== id),
    })),
  // Spawning is an event handed to the particle renderer, not state the store
  // holds for the effect's lifetime. `effects` is now a bounded ring of recent
  // spawns kept purely so the debug bridge can report what fired; the renderer
  // owns lifetime, so nothing writes to the store when an effect ends.
  spawnEffect: (effect) => {
    const spawned = publishEffect(effect)
    set((state) => ({
      effects: [...state.effects, spawned].slice(-RECENT_EFFECT_LIMIT),
    }))
  },
  publishImpact: (event) => {
    get().spawnEffect(createImpactEffect(event))
    if (event.playAudio !== false) {
      audioEngine.playImpact({
        tier: event.tier,
        pan: Math.max(-1, Math.min(1, event.direction?.[0] ?? 0)),
        source: event.source === 'environment' ? undefined : event.source,
        weaponId: event.weaponId,
      })
    }
    if ((event.cameraTrauma ?? 0) > 0 || (event.cameraKick ?? 0) > 0) {
      requestCameraImpact(
        {
          x: event.direction?.[0] ?? 0,
          z: event.direction?.[2] ?? 1,
        },
        event.cameraTrauma ?? 0,
        event.cameraKick ?? 0,
      )
    }
    if ((event.hitstopSeconds ?? 0) > 0) {
      requestHitstop(event.hitstopSeconds ?? 0)
    }
    if (event.rumble && typeof navigator !== 'undefined') {
      const gamepad = navigator.getGamepads
        ? getPrimaryGamepad(
            navigator.getGamepads() as unknown as readonly (GamepadLike | null)[],
          )
        : null
      rumbleGamepad(
        gamepad,
        get().settings.gamepadVibration,
        event.rumble.intensity,
        event.rumble.durationMs,
      )
    }
  },
  setThreat: (threat) =>
    set((state) => ({
      threats: [
        ...state.threats.filter((item) => item.id !== threat.id),
        threat,
      ],
    })),
  clearThreat: (id) =>
    set((state) => ({
      threats: state.threats.filter((item) => item.id !== id),
    })),
  setMasterVolume: (value) => {
    audioEngine.setVolume(value)
    set((state) => ({ settings: { ...state.settings, masterVolume: value } }))
  },
  setMusicVolume: (value) => {
    const musicVolume = Math.max(0, Math.min(1, value))
    audioEngine.setMix({ music: musicVolume })
    set((state) => ({ settings: { ...state.settings, musicVolume } }))
  },
  setSfxVolume: (value) => {
    const sfxVolume = Math.max(0, Math.min(1, value))
    audioEngine.setMix({ sfx: sfxVolume, ui: sfxVolume })
    set((state) => ({ settings: { ...state.settings, sfxVolume } }))
  },
  setVisionAssist: (value) =>
    set((state) => ({ settings: { ...state.settings, visionAssist: value } })),
  setReducedMotion: (value) =>
    set((state) => ({ settings: { ...state.settings, reducedMotion: value } })),
  setGamepadVibration: (value) =>
    set((state) => ({
      settings: { ...state.settings, gamepadVibration: value },
    })),
  setLastInputDevice: (device) =>
    set((state) =>
      state.lastInputDevice === device ? state : { lastInputDevice: device },
    ),
}))

export function makeRuntimeId(prefix: string): string {
  return nextId(prefix)
}
