import type { EffectSpawn } from '../../runtime/gameStore'
import type { WeaponId } from '../../game/runBuild'

export type ImpactTier =
  'normal' | 'critical' | 'kill' | 'boss-kill' | 'player-hit' | 'wall'

export type ImpactSource = 'player' | 'enemy' | 'environment'

export interface ImpactFeedbackEvent {
  readonly id: string
  readonly tier: ImpactTier
  readonly position: readonly [number, number, number]
  readonly direction?: readonly [number, number, number]
  readonly source: ImpactSource
  readonly weaponId?: WeaponId
  readonly wallCollision?: boolean
  readonly color?: string
}

export interface ImpactVisualProfile {
  readonly durationMs: number
  readonly shardCount: number
  readonly hasRing: boolean
  readonly coreScale: number
  readonly ringScale: number
  readonly hdrIntensity: 1.6 | 2.3 | 3
}

export interface ImpactEffectSpawn extends EffectSpawn {
  readonly impactTier: ImpactTier
  readonly impactSource: ImpactSource
  readonly weaponId?: WeaponId
  readonly wallCollision: boolean
}

const IMPACT_PROFILES: Readonly<Record<ImpactTier, ImpactVisualProfile>> = {
  normal: {
    durationMs: 220,
    shardCount: 6,
    hasRing: false,
    coreScale: 0.12,
    ringScale: 0,
    hdrIntensity: 1.6,
  },
  critical: {
    durationMs: 320,
    shardCount: 10,
    hasRing: true,
    coreScale: 0.162,
    ringScale: 0.88,
    hdrIntensity: 2.3,
  },
  kill: {
    durationMs: 480,
    shardCount: 16,
    hasRing: true,
    coreScale: 0.19,
    ringScale: 1.1,
    hdrIntensity: 2.3,
  },
  'boss-kill': {
    durationMs: 720,
    shardCount: 24,
    hasRing: true,
    coreScale: 0.27,
    ringScale: 1.85,
    hdrIntensity: 3,
  },
  'player-hit': {
    durationMs: 360,
    shardCount: 10,
    hasRing: false,
    coreScale: 0.19,
    ringScale: 0,
    hdrIntensity: 2.3,
  },
  wall: {
    durationMs: 160,
    shardCount: 4,
    hasRing: false,
    coreScale: 0.095,
    ringScale: 0,
    hdrIntensity: 1.6,
  },
}

export function getImpactVisualProfile(tier: ImpactTier): ImpactVisualProfile {
  return IMPACT_PROFILES[tier]
}

function defaultImpactColor(source: ImpactSource): string {
  return source === 'player' ? '#62f5e8' : '#ffffff'
}

function effectKindForTier(tier: ImpactTier): EffectSpawn['kind'] {
  if (tier === 'kill' || tier === 'boss-kill') return 'death'
  if (tier === 'player-hit') return 'hurt'
  if (tier === 'wall') return 'burst'
  return 'hit'
}

/**
 * Converts a simulation-owned feedback event into one composite pool spawn.
 * The particle pool expands this single event into its core, shards, and ring,
 * so audio/VFX call sites do not need to publish three duplicate hit events.
 */
export function createImpactEffect(
  event: ImpactFeedbackEvent,
): ImpactEffectSpawn {
  const profile = getImpactVisualProfile(event.tier)
  return {
    id: event.id,
    kind: effectKindForTier(event.tier),
    position: [...event.position],
    direction: event.direction ? [...event.direction] : undefined,
    color: event.color ?? defaultImpactColor(event.source),
    durationMs: profile.durationMs,
    width: profile.ringScale || 1,
    impactTier: event.tier,
    impactSource: event.source,
    weaponId: event.weaponId,
    wallCollision: event.wallCollision ?? event.tier === 'wall',
  }
}

export function isImpactEffect(
  effect: EffectSpawn,
): effect is ImpactEffectSpawn {
  return 'impactTier' in effect
}
