import { getDifficultyRankDefinition } from './difficulty'
import type { ChamberLevel, DifficultyRank } from './types'

export type AttackDirectorTier = ChamberLevel | 'boss'
export type AttackKind = 'melee' | 'ranged'

export interface AttackTokenCaps {
  readonly total: number
  readonly ranged: number
}

export interface AttackToken {
  readonly enemyId: string
  readonly kind: AttackKind
}

export interface AttackDirectorSnapshot {
  readonly caps: AttackTokenCaps
  readonly used: number
  readonly rangedUsed: number
  readonly holders: readonly AttackToken[]
}

export interface AttackDirector {
  /** Idempotently acquires a token. A holder must release before changing kind. */
  acquire(enemyId: string, kind: AttackKind): boolean
  /** Releases only token ownership; windup/recovery state remains caller-owned. */
  release(enemyId: string): boolean
  has(enemyId: string): boolean
  heldKind(enemyId: string): AttackKind | null
  snapshot(): AttackDirectorSnapshot
  clear(): void
}

function getBaseAttackTokenCaps(
  encounter: AttackDirectorTier,
): AttackTokenCaps {
  const chamber = encounter === 'boss' ? 10 : encounter
  return chamber === 1
    ? { total: 2, ranged: 1 }
    : chamber === 2
      ? { total: 3, ranged: 1 }
      : { total: 4, ranged: 2 }
}

export function getAttackTokenCaps(
  encounter: AttackDirectorTier,
  difficulty: DifficultyRank = 1,
): AttackTokenCaps {
  const base = getBaseAttackTokenCaps(encounter)
  const rank = getDifficultyRankDefinition(difficulty)
  return Object.freeze({
    total: base.total + rank.attackTokenBonus,
    ranged: base.ranged + rank.rangedTokenBonus,
  })
}

/** Creates an isolated, deterministic first-requested token pool for one room. */
export function createAttackDirector(
  encounter: AttackDirectorTier,
  difficulty: DifficultyRank = 1,
): AttackDirector {
  const caps = getAttackTokenCaps(encounter, difficulty)
  const holders = new Map<string, AttackKind>()

  const rangedUsed = (): number =>
    [...holders.values()].filter((kind) => kind === 'ranged').length

  return {
    acquire(enemyId, kind) {
      if (enemyId.length === 0) {
        return false
      }

      const held = holders.get(enemyId)
      if (held !== undefined) {
        return held === kind
      }
      if (holders.size >= caps.total) {
        return false
      }
      if (kind === 'ranged' && rangedUsed() >= caps.ranged) {
        return false
      }

      holders.set(enemyId, kind)
      return true
    },

    release(enemyId) {
      return holders.delete(enemyId)
    },

    has(enemyId) {
      return holders.has(enemyId)
    },

    heldKind(enemyId) {
      return holders.get(enemyId) ?? null
    },

    snapshot() {
      const tokens = [...holders.entries()]
        .map(([enemyId, kind]) => ({ enemyId, kind }))
        .sort((a, b) => a.enemyId.localeCompare(b.enemyId, 'en'))

      return {
        caps,
        used: holders.size,
        rangedUsed: rangedUsed(),
        holders: tokens,
      }
    },

    clear() {
      holders.clear()
    },
  }
}
