export const ITEM_IDS = ITEMS.map((item) => item.id) as ItemId[]

export const STARTER_ITEM_IDS = [
  'starter-blade',
  'starter-coat',
] as const satisfies readonly ItemId[]

export const DEFAULT_LOADOUT: EquipmentLoadout = Object.freeze({
  weapon: 'starter-blade',
  armor: 'starter-coat',
  charm: null,
})

const itemById = new Map<ItemId, ItemDefinition>(
  ITEMS.map((item) => [item.id, item]),
)

export type MetaMutationFailure =
  | 'unknown-item'
  | 'already-owned'
  | 'insufficient-funds'
  | 'not-owned'
  | 'wrong-slot'
  | 'required-slot'

export type MetaMutationResult =
  | { readonly ok: true; readonly meta: MetaProgression }
  | {
      readonly ok: false
      readonly meta: MetaProgression
      readonly reason: MetaMutationFailure
    }

export function isItemId(value: unknown): value is ItemId {
  return typeof value === 'string' && itemById.has(value as ItemId)
}

export function getItem(id: ItemId): ItemDefinition {
  const item = itemById.get(id)
  if (item === undefined) throw new RangeError(`Unknown item: ${id}`)
  return item
}

export function canonicalizeOwnedItemIds(itemIds: readonly ItemId[]): ItemId[] {
  const owned = new Set(itemIds)
  return ITEM_IDS.filter((id) => owned.has(id))
}

export function deriveLoadoutStats(
  loadout: EquipmentLoadout,
  base: PlayerStats = BASE_PLAYER_STATS,
  caps?: PlayerStatCaps,
): PlayerStats {
  const equipped = [
    ['weapon', loadout.weapon],
    ['armor', loadout.armor],
    ['charm', loadout.charm],
  ] as const satisfies ReadonlyArray<readonly [EquipmentSlot, ItemId | null]>

  return equipped.reduce((stats, [slot, itemId]) => {
    if (itemId === null) return stats
    const item = getItem(itemId)
    if (item.slot !== slot) {
      throw new TypeError(`Item ${itemId} cannot be equipped in ${slot}`)
    }
    return applyStatModifiers(stats, item.modifiers, caps)
  }, base)
}

function failure(
  meta: MetaProgression,
  reason: MetaMutationFailure,
): MetaMutationResult {
  return { ok: false, meta, reason }
}

export function purchaseItem(
  meta: MetaProgression,
  itemId: string,
): MetaMutationResult {
  if (!isItemId(itemId)) return failure(meta, 'unknown-item')
  if (meta.ownedItemIds.includes(itemId)) {
    return failure(meta, 'already-owned')
  }

  const item = getItem(itemId)
  if (meta.currency < item.cost) return failure(meta, 'insufficient-funds')

  return {
    ok: true,
    meta: {
      ...meta,
      currency: meta.currency - item.cost,
      ownedItemIds: canonicalizeOwnedItemIds([...meta.ownedItemIds, itemId]),
    },
  }
}

export function setEquippedItem(
  meta: MetaProgression,
  slot: EquipmentSlot,
  itemId: string | null,
): MetaMutationResult {
  if (itemId === null) {
    if (slot !== 'charm') return failure(meta, 'required-slot')
    return {
      ok: true,
      meta: { ...meta, loadout: { ...meta.loadout, charm: null } },
    }
  }
  if (!isItemId(itemId)) return failure(meta, 'unknown-item')
  if (!meta.ownedItemIds.includes(itemId)) return failure(meta, 'not-owned')
  if (getItem(itemId).slot !== slot) return failure(meta, 'wrong-slot')

  const loadout: EquipmentLoadout =
    slot === 'weapon'
      ? { ...meta.loadout, weapon: itemId }
      : slot === 'armor'
        ? { ...meta.loadout, armor: itemId }
        : { ...meta.loadout, charm: itemId }

  return { ok: true, meta: { ...meta, loadout } }
}
