export const UPGRADES = [
  ...RUNE_DEFINITIONS,
  LEGACY_IRON_HEART,
] as const satisfies readonly UpgradeDefinition[]

export const RUNE_IDS = RUNE_DEFINITIONS.map((rune) => rune.id) as RuneId[]

export const UPGRADE_IDS = UPGRADES.map((upgrade) => upgrade.id) as UpgradeId[]

const upgradeById = new Map<UpgradeId, UpgradeDefinition>(
  UPGRADES.map((upgrade) => [upgrade.id, upgrade]),
)

export function getUpgrade(id: UpgradeId): UpgradeDefinition {
  const upgrade = upgradeById.get(id)
  if (upgrade === undefined) {
    throw new RangeError(`Unknown upgrade: ${id}`)
  }
  return upgrade
}

export function applyUpgrade(
  stats: PlayerStats,
  upgrade: UpgradeDefinition,
  caps: PlayerStatCaps = PLAYER_STAT_CAPS,
): PlayerStats {
  return applyStatModifiers(stats, upgrade.modifiers, caps)
}

/**
 * A cap limits what an upgrade may *add*; it must never confiscate what the
 * build already holds. Passive stacks push several of these stats past their
 * upgrade ceiling, and clamping to the raw cap would delete that progress the
 * next time any upgrade touched the same stat.
 */
function ceiling(cap: number, current: number): number {
  return Math.max(cap, current)
}

export function applyStatModifiers(
  stats: PlayerStats,
  modifiers: StatModifiers,
  caps: PlayerStatCaps = PLAYER_STAT_CAPS,
): PlayerStats {
  return {
    maxHealth: Math.min(
      ceiling(caps.maxHealth, stats.maxHealth),
      Math.max(1, stats.maxHealth + (modifiers.maxHealthAdd ?? 0)),
    ),
    moveSpeed: Math.min(
      ceiling(caps.moveSpeed, stats.moveSpeed),
      Math.max(0, stats.moveSpeed * (modifiers.moveSpeedMultiplier ?? 1)),
    ),
    attackDamage: Math.min(
      ceiling(caps.attackDamage, stats.attackDamage),
      Math.max(0, stats.attackDamage * (modifiers.attackDamageMultiplier ?? 1)),
    ),
    attackCooldownMs: Math.max(
      caps.minAttackCooldownMs,
      stats.attackCooldownMs * (modifiers.attackCooldownMultiplier ?? 1),
    ),
    attackRange: Math.max(
      0,
      stats.attackRange + (modifiers.attackRangeAdd ?? 0),
    ),
    projectileSpeed: Math.max(
      0,
      stats.projectileSpeed * (modifiers.projectileSpeedMultiplier ?? 1),
    ),
    dodgeCooldownMs: Math.max(
      caps.minDodgeCooldownMs,
      stats.dodgeCooldownMs * (modifiers.dodgeCooldownMultiplier ?? 1),
    ),
    visionRange: Math.min(
      ceiling(caps.visionRange, stats.visionRange),
      Math.max(0, stats.visionRange + (modifiers.visionRangeAdd ?? 0)),
    ),
    visionFovDeg: Math.min(
      ceiling(caps.visionFovDeg, stats.visionFovDeg),
      Math.max(0, stats.visionFovDeg + (modifiers.visionFovDegAdd ?? 0)),
    ),
  }
}
