import { Vector2, Vector3, type Object3D } from 'three'

import type { CombatantArchetypeId, ObservationMode } from '../game/types'
import type { DamagePacket } from '../game/runBuild'
import type { InputDevice } from './inputActions'

export interface EnemyRuntimeHandle {
  id: string
  archetypeId: CombatantArchetypeId
  position: Vector3
  /** True only while the player's gaze is actively freezing this enemy. */
  observed: boolean
  /** True while any observation rule currently pauses this enemy. */
  frozen: boolean
  observationMode: ObservationMode
  observationProgress: number
  observationBroken: boolean
  /** Current health normalized to [0, 1]; drives projectile target priority. */
  healthRatio: number
  /** Immediately releases gaze freeze and grants brief gaze immunity. */
  dispelObservation: (durationMs: number) => void
  takeHit: (
    damage: number | DamagePacket,
    direction: Vector3,
    knockback: number,
    impactPosition?: Vector3,
  ) => void
}

export interface ShardPickup {
  id: string
  x: number
  z: number
  /** runtime.elapsed at spawn; drives the arm delay and hover phase. */
  bornAt: number
  value: number
}

export interface RuntimeRegistry {
  elapsed: number
  /** World-presentation time, held by hitstop while seed/UI time continues. */
  presentationElapsed: number
  playerPosition: Vector3
  /**
   * Where the player *appears* to be. Normally the body; during the death
   * throw the body is frozen by the paused physics world while the visual
   * sails backward, and effects that frame the character — the death iris
   * above all — have to follow the silhouette, not the corpse's collider.
   */
  playerFocusPosition: Vector3
  playerFacing: Vector3
  /** Actual rendered mesh forward; differs from aim only during a dash roll. */
  playerVisualFacing: Vector3
  /** True for the full authored dash action, not only its movement impulse. */
  playerDashVisualActive: boolean
  playerInputReady: boolean
  activeInputDevice: InputDevice
  /**
   * The equipped-weapon group, published so tests can measure what actually
   * reached the scene. Null outside a run and in any build without the rig
   * mounted; nothing in gameplay reads it.
   */
  weaponRig: Object3D | null
  /** Shared nearest enemy used by the floating arsenal, never player gaze. */
  weaponTargetId: string | null
  /** World-space muzzle positions published by the visual hardpoints. */
  weaponMuzzles: Map<string, Vector3>
  playerInvulnerableUntil: number
  cameraTrauma: number
  cameraKick: number
  /** Direction owned by the current camera impact, independent of aim/dash. */
  cameraImpactDirection: Vector3
  playerHitDirection: Vector3
  pointerNdc: Vector2
  pressedKeys: Set<string>
  enemies: Map<string, EnemyRuntimeHandle>
  /** Kill-dropped shard pickups awaiting collection, mutated by the scene. */
  shards: ShardPickup[]
}

export const runtime: RuntimeRegistry = {
  elapsed: 0,
  presentationElapsed: 0,
  playerPosition: new Vector3(0, 0.8, 0),
  playerFocusPosition: new Vector3(0, 0.8, 0),
  playerFacing: new Vector3(0, 0, -1),
  playerVisualFacing: new Vector3(0, 0, -1),
  playerDashVisualActive: false,
  playerInputReady: false,
  activeInputDevice: 'keyboard-mouse',
  weaponRig: null,
  weaponTargetId: null,
  weaponMuzzles: new Map(),
  playerInvulnerableUntil: 0,
  cameraTrauma: 0,
  cameraKick: 0,
  cameraImpactDirection: new Vector3(0, 0, 1),
  playerHitDirection: new Vector3(0, 0, 1),
  pointerNdc: new Vector2(),
  pressedKeys: new Set(),
  enemies: new Map(),
  shards: [],
}

export function resetRuntime(): void {
  runtime.elapsed = 0
  runtime.presentationElapsed = 0
  runtime.playerPosition.set(0, 0.8, 0)
  runtime.playerFocusPosition.set(0, 0.8, 0)
  runtime.playerFacing.set(0, 0, -1)
  runtime.playerVisualFacing.set(0, 0, -1)
  runtime.playerDashVisualActive = false
  runtime.playerInputReady = false
  runtime.activeInputDevice = 'keyboard-mouse'
  runtime.weaponRig = null
  runtime.weaponTargetId = null
  runtime.weaponMuzzles.clear()
  runtime.playerInvulnerableUntil = 0
  runtime.cameraTrauma = 0
  runtime.cameraKick = 0
  runtime.cameraImpactDirection.set(0, 0, 1)
  runtime.playerHitDirection.set(0, 0, 1)
  runtime.pointerNdc.set(0, 0)
  runtime.pressedKeys.clear()
  runtime.enemies.clear()
  runtime.shards.length = 0
}

/**
 * Publishes one camera impulse without borrowing the player's last aim or dash
 * direction. Stronger overlapping impacts win, while the direction always
 * follows the newest readable contact.
 */
export function requestCameraImpact(
  direction: Readonly<{ x: number; z: number }>,
  trauma: number,
  kick: number,
): void {
  const impactDirection = runtime.cameraImpactDirection.set(
    Number.isFinite(direction.x) ? direction.x : 0,
    0,
    Number.isFinite(direction.z) ? direction.z : 0,
  )
  if (impactDirection.lengthSq() < 0.0001) impactDirection.set(0, 0, 1)
  else impactDirection.normalize()
  runtime.cameraTrauma = Math.max(
    runtime.cameraTrauma,
    Number.isFinite(trauma) ? Math.max(0, trauma) : 0,
  )
  runtime.cameraKick = Math.max(
    runtime.cameraKick,
    Number.isFinite(kick) ? Math.max(0, kick) : 0,
  )
}
