const LAYOUT_VARIANTS = ['original', 'mirror-x', 'rotate-180'] as const

export function applyLayoutVariant(
  position: Vec2,
  variant: LayoutVariant,
): Vec2 {
  if (variant === 'mirror-x') return { x: -position.x, z: position.z }
  if (variant === 'rotate-180') return { x: -position.x, z: -position.z }
  return { ...position }
}

function getSpawnSlots(template: RoomTemplate) {
  return template.spawns.filter(
    (spawn) => spawn.role === 'enemy' || spawn.role === 'boss',
  )
}

function assignEliteAffixes(
  seed: string,
  nodeId: string,
  roster: readonly CombatantArchetypeId[],
  requestedCount: number,
): Array<EliteAffixId | null> {
  const result: Array<EliteAffixId | null> = roster.map(() => null)
  const eligible = roster.flatMap((id, index) =>
    id === 'grave-warden' ||
    id === 'moonbriar-queen' ||
    id === 'parallax-seraph' ||
    id === 'null-crown'
      ? []
      : [index],
  )
  const stream = createRandomStream(seed, `elites:${nodeId}`)
  const selected = stream.shuffle(eligible).slice(0, requestedCount)
  const affixes = stream.shuffle(ELITE_AFFIX_IDS)
  selected.forEach((rosterIndex, index) => {
    result[rosterIndex] = affixes[index % affixes.length] as EliteAffixId
  })
  return result
}

function createEnemies(
  seed: string,
  nodeId: string,
  template: RoomTemplate,
  chamber: ChamberLevel,
  layoutVariant: LayoutVariant,
  routeRisk: RouteRisk,
  difficulty: DifficultyRank,
  mutationId: RoomMutationId | null,
  bossId: BossArchetypeId | null,
): GeneratedEnemySpawn[] {
  const baseRoster: readonly CombatantArchetypeId[] =
    chamber === FINAL_CHAMBER && bossId !== null
      ? BOSS_ROSTERS[bossId]
      : CHAMBER_ROSTERS[chamber]
  const normalEnemyBonus =
    mutationId === null
      ? 0
      : ROOM_MUTATION_DEFINITIONS[mutationId].normalEnemyBonus
  const slots = getSpawnSlots(template)
  if (slots.length < baseRoster.length) {
    throw new Error(`Room template ${template.id} has too few combat slots`)
  }
  const availableBonusSlots = Math.max(0, slots.length - baseRoster.length)
  const roster: CombatantArchetypeId[] = [
    ...baseRoster,
    ...Array.from<CombatantArchetypeId>({
      length: Math.min(normalEnemyBonus, availableBonusSlots),
    }).fill('grave-husk'),
  ]
  const orderedSlots =
    chamber === 1 || chamber === FINAL_CHAMBER
      ? slots.slice(0, roster.length)
      : createRandomStream(seed, `spawns:${nodeId}`)
          .shuffle(slots)
          .slice(0, roster.length)
  const eligibleCount = roster.filter(
    (id) =>
      id !== 'grave-warden' &&
      id !== 'moonbriar-queen' &&
      id !== 'parallax-seraph' &&
      id !== 'null-crown',
  ).length
  const eliteCount = getEncounterEliteCount(
    chamber,
    difficulty,
    routeRisk,
    eligibleCount,
    mutationId,
  )
  const affixes = assignEliteAffixes(seed, nodeId, roster, eliteCount)

  return roster.map((archetypeId, index) => {
    const slot = orderedSlots[index]
    if (slot === undefined) throw new Error('Missing generated enemy slot')
    return {
      spawnId: slot.id,
      position: applyLayoutVariant(slot.position, layoutVariant),
      archetypeId,
      eliteAffixId: affixes[index] ?? null,
    }
  })
}

function combatTier(chamber: ChamberLevel): CombatTier | null {
  if (chamber === FINAL_CHAMBER) return null
  if (chamber === 1) return 1
  if (chamber === 2) return 2
  return 3
}

interface NodeDraft {
  id: string
  chamber: ChamberLevel
  template: RoomTemplate
  routeRisk: RouteRisk
  mutationId: RoomMutationId | null
  bossId: BossArchetypeId | null
  nextNodeIds: readonly string[]
  layoutVariant: LayoutVariant
}

function toNode(
  seed: string,
  difficulty: DifficultyRank,
  draft: NodeDraft,
): GeneratedRunNode {
  const enemies = createEnemies(
    seed,
    draft.id,
    draft.template,
    draft.chamber,
    draft.layoutVariant,
    draft.routeRisk,
    difficulty,
    draft.mutationId,
    draft.bossId,
  )
  return {
    id: draft.id,
    index: draft.chamber - 1,
    depth: draft.chamber,
    chamberLevel: draft.chamber,
    templateId: draft.template.id,
    layoutVariant: draft.layoutVariant,
    kind: draft.chamber === FINAL_CHAMBER ? 'boss' : 'combat',
    combatTier: combatTier(draft.chamber),
    enemies,
    biomeId: draft.template.biomeId,
    routeRisk: draft.routeRisk,
    nextNodeIds: draft.nextNodeIds,
    eliteCount: enemies.filter((enemy) => enemy.eliteAffixId !== null).length,
    mutationId: draft.mutationId,
    bossId: draft.bossId,
  }
}

function pickLayout(seed: string, nodeId: string): LayoutVariant {
  return createRandomStream(seed, `layout:${nodeId}`).pick(LAYOUT_VARIANTS)
}

function templatesForBiome(biomeId: RoomTemplate['biomeId']): RoomTemplate[] {
  return ROOM_TEMPLATES.filter(
    (template) => template.kind === 'combat' && template.biomeId === biomeId,
  )
}

function buildDrafts(
  seed: string,
  difficulty: DifficultyRank,
  startTemplateId?: string,
): NodeDraft[] {
  const cryptTemplates = templatesForBiome('crypt')
  const moonTemplates = templatesForBiome('moon-garden')
  const warden = ROOM_TEMPLATES.find(
    (template) => template.id === 'warden-throne',
  )
  const queen = ROOM_TEMPLATES.find(
    (template) => template.id === 'briar-sanctum',
  )
  if (
    cryptTemplates.length < 5 ||
    moonTemplates.length < 4 ||
    !warden ||
    !queen
  ) {
    throw new Error(
      'Run graph requires five Crypt rooms, four Moon Garden rooms, and two bosses',
    )
  }

  // A requested arena replaces chamber one. Only combat rooms qualify: a boss
  // chamber has one occupant and no survival pacing, so opening a run there
  // would be an empty arena, not a harder one.
  const requested =
    startTemplateId === undefined
      ? undefined
      : ROOM_TEMPLATES.find(
          (template) =>
            template.id === startTemplateId && template.kind === 'combat',
        )
  if (startTemplateId !== undefined && requested === undefined) {
    throw new RangeError(`Unknown survival arena: ${startTemplateId}`)
  }

  const first =
    requested ??
    cryptTemplates.find((template) => template.id === 'crypt-crossing')
  if (!first) throw new Error('Missing Crypt Crossing')
  const cryptOrder = [
    first,
    ...createRandomStream(seed, 'map:crypt').shuffle(
      cryptTemplates.filter((template) => template !== first),
    ),
  ].slice(0, 5)
  const moonStable = createRandomStream(seed, 'map:moon:stable').shuffle(
    moonTemplates,
  )
  const moonVolatile = createRandomStream(seed, 'map:moon:volatile').shuffle(
    moonTemplates,
  )
  const mutationStream = createRandomStream(seed, 'mutations:moon')
  const moonMutationIds = ROOM_MUTATION_IDS.filter((id) => id !== 'double-omen')
  const volatileMutations: RoomMutationId[] = []
  for (let index = 0; index < 4; index += 1) {
    const previous = volatileMutations[index - 1]
    volatileMutations.push(
      mutationStream.pick(moonMutationIds.filter((id) => id !== previous)),
    )
  }

  const drafts: NodeDraft[] = []
  for (let depth = 1; depth <= 5; depth += 1) {
    const chamber = depth as ChamberLevel
    drafts.push({
      id: `crypt-${depth}`,
      chamber,
      template: cryptOrder[depth - 1] as RoomTemplate,
      routeRisk: 'fixed',
      mutationId:
        difficulty >= 5 && (depth === 2 || depth === 4)
          ? 'double-omen'
          : difficulty >= 4 && (depth === 2 || depth === 4)
            ? createRandomStream(seed, `mutations:crypt-seal-${depth}`).pick([
                'restless-swarm',
                'elite-oath',
              ] as const)
            : depth === 3
              ? createRandomStream(seed, 'mutations:crypt-intro').pick([
                  'open-ground',
                  'restless-swarm',
                ] as const)
              : null,
      bossId: null,
      nextNodeIds:
        depth < 5
          ? [`crypt-${depth + 1}`]
          : ['moon-6-stable', 'moon-6-volatile'],
      layoutVariant:
        depth === 1 ? 'original' : pickLayout(seed, `crypt-${depth}`),
    })
  }

  for (let depth = 6; depth <= 9; depth += 1) {
    const chamber = depth as ChamberLevel
    const next =
      depth < 9
        ? [`moon-${depth + 1}-stable`, `moon-${depth + 1}-volatile`]
        : ['boss-warden', 'boss-moonbriar']
    drafts.push({
      id: `moon-${depth}-stable`,
      chamber,
      template: moonStable[depth - 6] as RoomTemplate,
      routeRisk: 'stable',
      mutationId: null,
      bossId: null,
      nextNodeIds: next,
      layoutVariant: pickLayout(seed, `moon-${depth}-stable`),
    })
    drafts.push({
      id: `moon-${depth}-volatile`,
      chamber,
      template: moonVolatile[depth - 6] as RoomTemplate,
      routeRisk: 'volatile',
      mutationId: volatileMutations[depth - 6] as RoomMutationId,
      bossId: null,
      nextNodeIds: next,
      layoutVariant: pickLayout(seed, `moon-${depth}-volatile`),
    })
  }

  drafts.push(
    {
      id: 'boss-warden',
      chamber: 10,
      template: warden,
      routeRisk: 'boss',
      mutationId: null,
      bossId: 'grave-warden',
      nextNodeIds: [],
      layoutVariant: 'original',
    },
    {
      id: 'boss-moonbriar',
      chamber: 10,
      template: queen,
      routeRisk: 'boss',
      mutationId: null,
      bossId: 'moonbriar-queen',
      nextNodeIds: [],
      layoutVariant: 'original',
    },
  )
  return drafts
}

export function createRun(
  seedInput: SeedInput,
  difficulty: DifficultyRank = 1,
  options: CreateRunOptions = {},
): GeneratedRun {
  if (!isDifficultyRank(difficulty)) {
    throw new RangeError(`Unsupported difficulty rank: ${difficulty}`)
  }
  if (options.mode === 'endless') {
    return createEndlessCycle(seedInput, difficulty, 0, {
      routeMapUnlocked: options.routeMapUnlocked,
      startTemplateId: options.startTemplateId,
    })
  }
  const seed = normalizeRunSeed(seedInput)
  const mode = options.mode ?? 'standard'
  const dailyDateKey = options.dailyDateKey ?? null
  if (mode === 'daily' && !isDailyDateKey(dailyDateKey)) {
    throw new RangeError('Daily runs require a valid KST date key')
  }
  // Initialize all named streams up front so accidental stream removal is caught
  // by deterministic tests even though node-local streams perform the draws.
  createRunRandomStreams(seed)
  const rooms = buildDrafts(seed, difficulty, options.startTemplateId).map(
    (draft) => toNode(seed, difficulty, draft),
  )
  return {
    seed,
    difficulty,
    mode,
    dailyDateKey,
    startNodeId: 'crypt-1',
    routeMapUnlocked: options.routeMapUnlocked ?? false,
    rooms,
  }
}

/**
 * Builds one deterministic ten-chamber segment of an endless expedition.
 * Authored chamber rules keep using the local 1..10 `chamberLevel`, while
 * `depth`, `index`, and node ids are offset so runtime/UI state can count
 * 11, 12, ... without colliding with an earlier cycle.
 */
export function createEndlessCycle(
  rootSeedInput: SeedInput,
  difficulty: DifficultyRank,
  cycleIndex: number,
  options: Pick<CreateRunOptions, 'routeMapUnlocked' | 'startTemplateId'> = {},
): GeneratedRun {
  if (!Number.isSafeInteger(cycleIndex) || cycleIndex < 0) {
    throw new RangeError(`Invalid endless cycle index: ${cycleIndex}`)
  }
  const rootSeed = normalizeRunSeed(rootSeedInput)
  const cycleSeed = `${rootSeed}:endless:${cycleIndex}`
  const cycleRun = createRun(cycleSeed, difficulty, {
    mode: 'standard',
    routeMapUnlocked: options.routeMapUnlocked,
    startTemplateId: options.startTemplateId,
  })
  const offset = cycleIndex * FINAL_CHAMBER
  const prefix = `endless-${cycleIndex + 1}-`
  const qualifyNodeId = (nodeId: string) => `${prefix}${nodeId}`
  const rooms = cycleRun.rooms.map((node) => ({
    ...node,
    id: qualifyNodeId(node.id),
    index: node.index + offset,
    depth: node.depth + offset,
    nextNodeIds: node.nextNodeIds.map(qualifyNodeId),
  }))

  return {
    ...cycleRun,
    seed: rootSeed,
    mode: 'endless',
    dailyDateKey: null,
    startNodeId: qualifyNodeId(cycleRun.startNodeId),
    rooms,
  }
}

export function getRoomNode(
  run: GeneratedRun,
  nodeId: string,
): GeneratedRunNode {
  const node = run.rooms.find((room) => room.id === nodeId)
  if (node === undefined) throw new RangeError(`Unknown run node: ${nodeId}`)
  return node
}

export function getRouteChoices(
  run: GeneratedRun,
  nodeId: string,
): readonly GeneratedRunNode[] {
  const node = getRoomNode(run, nodeId)
  const choices = node.nextNodeIds.map((id) => getRoomNode(run, id))
  if (run.routeMapUnlocked || choices.length <= 1) return choices
  const canonical =
    choices.find((choice) => choice.routeRisk === 'stable') ??
    choices.find((choice) => choice.bossId === 'grave-warden') ??
    choices[0]
  return canonical ? [canonical] : []
}

export function getCanonicalRoute(
  run: GeneratedRun,
): readonly GeneratedRunNode[] {
  const route: GeneratedRunNode[] = []
  let node = getRoomNode(run, run.startNodeId)
  while (true) {
    route.push(node)
    const next = getRouteChoices(run, node.id)[0]
    if (next === undefined) return route
    node = next
  }
}
