export const WEAPON_IDS = WEAPON_DEFINITIONS.map(
  (definition) => definition.id,
) as WeaponId[]

export const RANGED_WEAPON_IDS = WEAPON_DEFINITIONS.filter(
  (definition) => definition.category === 'ranged',
).map((definition) => definition.id) as RangedWeaponId[]

const weaponById = new Map<WeaponId, WeaponDefinition>(
  WEAPON_DEFINITIONS.map((definition) => [definition.id, definition]),
)

export function isWeaponId(value: unknown): value is WeaponId {
  return typeof value === 'string' && weaponById.has(value as WeaponId)
}

export function isRangedWeaponId(value: unknown): value is RangedWeaponId {
  return isWeaponId(value)
}

export function getWeaponDefinition(id: WeaponId): WeaponDefinition {
  const definition = weaponById.get(id)
  if (definition === undefined) throw new RangeError(`Unknown weapon: ${id}`)
  return definition
}

function finiteOr(value: number, fallback: number): number {
  return Number.isFinite(value) ? value : fallback
}

function safeMultiplier(value: number, minimum: number): number {
  return Math.max(minimum, finiteOr(value, 1))
}

function normalizeWeaponLevel(level: number): number {
  return Math.max(1, Math.min(MAX_WEAPON_LEVEL, Math.floor(finiteOr(level, 1))))
}

export function normalizeGlobalWeaponModifiers(
  modifiers: Partial<GlobalWeaponModifiers> = {},
): GlobalWeaponModifiers {
  return {
    damageMultiplier: safeMultiplier(
      modifiers.damageMultiplier ?? 1,
      WEAPON_STAT_LIMITS.positiveMultiplier,
    ),
    attackSpeedMultiplier: safeMultiplier(
      modifiers.attackSpeedMultiplier ?? 1,
      WEAPON_STAT_LIMITS.attackSpeedMultiplier,
    ),
    rangeMultiplier: safeMultiplier(
      modifiers.rangeMultiplier ?? 1,
      WEAPON_STAT_LIMITS.positiveMultiplier,
    ),
    projectileSpeedMultiplier: safeMultiplier(
      modifiers.projectileSpeedMultiplier ?? 1,
      WEAPON_STAT_LIMITS.positiveMultiplier,
    ),
    areaMultiplier: safeMultiplier(
      modifiers.areaMultiplier ?? 1,
      WEAPON_STAT_LIMITS.positiveMultiplier,
    ),
    projectileCountAdd: Math.max(
      0,
      Math.floor(finiteOr(modifiers.projectileCountAdd ?? 0, 0)),
    ),
    maxHitsAdd: Math.max(0, Math.floor(finiteOr(modifiers.maxHitsAdd ?? 0, 0))),
    criticalChanceAdd: finiteOr(modifiers.criticalChanceAdd ?? 0, 0),
    knockbackMultiplier: Math.max(
      0,
      finiteOr(modifiers.knockbackMultiplier ?? 1, 1),
    ),
    frozenTargetDamageMultiplier: safeMultiplier(
      modifiers.frozenTargetDamageMultiplier ?? 1,
      WEAPON_STAT_LIMITS.positiveMultiplier,
    ),
    unfrozenTargetDamageMultiplier: safeMultiplier(
      modifiers.unfrozenTargetDamageMultiplier ?? 1,
      WEAPON_STAT_LIMITS.positiveMultiplier,
    ),
  }
}

/** Resolves one weapon rank, then applies the run-wide passive modifiers. */
export function resolveWeaponStats(
  runWeapon: Pick<RunWeapon, 'weaponId' | 'level'>,
  globalModifiers: Partial<GlobalWeaponModifiers> = DEFAULT_GLOBAL_WEAPON_MODIFIERS,
): WeaponStats {
  const { weaponId: id, level } = runWeapon
  const definition = getWeaponDefinition(id)
  const safeLevel = normalizeWeaponLevel(level)
  const completedLevels = safeLevel - 1
  const evolved = safeLevel >= WEAPON_EVOLUTION_LEVEL
  const evolutionDamageMultiplier = evolved ? 1.35 : 1
  const evolutionAreaMultiplier = evolved ? 1.2 : 1
  const growth = definition.growth
  const global = normalizeGlobalWeaponModifiers(globalModifiers)
  const attackSpeedFromLevel = Math.max(
    WEAPON_STAT_LIMITS.attackSpeedMultiplier,
    1 + growth.attackSpeedPerLevel * completedLevels,
  )
  const projectileCountFromLevel = growth.projectileCountEveryLevels
    ? Math.floor(completedLevels / growth.projectileCountEveryLevels)
    : 0
  const maxHitsFromLevel = growth.maxHitsEveryLevels
    ? Math.floor(completedLevels / growth.maxHitsEveryLevels)
    : 0
  const projectileSpeed =
    definition.baseStats.projectileSpeed <= 0
      ? 0
      : Math.max(
          WEAPON_STAT_LIMITS.projectileSpeed,
          definition.baseStats.projectileSpeed *
            (1 + growth.projectileSpeedPerLevel * completedLevels) *
            global.projectileSpeedMultiplier,
        )

  return {
    damage: Math.max(
      WEAPON_STAT_LIMITS.damage,
      definition.baseStats.damage * WEAPON_STAT_LIMITS.minimumDamageFraction,
      definition.baseStats.damage *
        (1 + growth.damagePerLevel * completedLevels) *
        evolutionDamageMultiplier *
        global.damageMultiplier,
    ),
    cooldownMs: Math.max(
      WEAPON_STAT_LIMITS.cooldownMs,
      definition.baseStats.cooldownMs /
        (attackSpeedFromLevel * global.attackSpeedMultiplier),
    ),
    range: Math.max(
      WEAPON_STAT_LIMITS.range,
      definition.baseStats.range *
        (1 + growth.rangePerLevel * completedLevels) *
        global.rangeMultiplier,
    ),
    projectileSpeed,
    projectileCount: Math.max(
      1,
      definition.baseStats.projectileCount +
        projectileCountFromLevel +
        (evolved ? 1 : 0) +
        global.projectileCountAdd,
    ),
    maxHits: Math.max(
      1,
      definition.baseStats.maxHits +
        maxHitsFromLevel +
        (evolved ? 1 : 0) +
        global.maxHitsAdd,
    ),
    areaRadius: Math.max(
      0,
      definition.baseStats.areaRadius *
        (1 + growth.areaPerLevel * completedLevels) *
        evolutionAreaMultiplier *
        global.areaMultiplier,
    ),
    knockback: Math.max(
      0,
      definition.baseStats.knockback * global.knockbackMultiplier,
    ),
    criticalChance: Math.max(
      0,
      Math.min(
        WEAPON_STAT_LIMITS.maximumCriticalChance,
        definition.baseStats.criticalChance + global.criticalChanceAdd,
      ),
    ),
    criticalMultiplier: Math.max(
      WEAPON_STAT_LIMITS.criticalMultiplier,
      definition.baseStats.criticalMultiplier,
    ),
  }
}

export interface DamagePacket {
  /** Unique per attack or projectile; prevents one entity hitting twice. */
  readonly hitId: string
  readonly sourceWeaponId: WeaponId
  /** @deprecated Prefer sourceWeaponId in new combat adapters. */
  readonly weaponId: WeaponId
  readonly amount: number
  readonly knockback: number
  readonly critical: boolean
  readonly tags: readonly WeaponDamageTag[]
}

export function createDamagePacket(
  hitId: string,
  weaponId: WeaponId,
  stats: WeaponStats,
  critical = false,
): DamagePacket {
  const definition = getWeaponDefinition(weaponId)
  return {
    hitId,
    sourceWeaponId: weaponId,
    weaponId,
    amount: Math.max(
      0,
      finiteOr(stats.damage, 0) *
        (critical
          ? Math.max(
              WEAPON_STAT_LIMITS.criticalMultiplier,
              finiteOr(stats.criticalMultiplier, 1),
            )
          : 1),
    ),
    knockback: Math.max(0, finiteOr(stats.knockback, 0)),
    critical,
    tags: definition.tags,
  }
}

