export type InputDevice = 'keyboard-mouse' | 'gamepad' | 'touch'

export interface InputActionFrame {
  readonly moveX: number
  readonly moveZ: number
  readonly aimX: number
  readonly aimZ: number
  readonly aimActive: boolean
  /** Legacy compatibility signal. The Q / Y optic field was removed. */
  readonly overloadPressed: boolean
  /** Edge-triggered mobility burst; never doubles as a manual attack. */
  readonly dashPressed: boolean
  readonly pausePressed: boolean
  /**
   * Level signal, unlike the press edges above. The tactical scan is a hold on
   * both devices — `Tab` on keyboard, VIEW on a pad — so the HUD needs to know
   * the button is still down, not that it went down once.
   */
  readonly tacticalScanHeld: boolean
  readonly device: InputDevice
  readonly gamepad: GamepadLike | null
}

export interface GamepadButtonLike {
  readonly pressed: boolean
  readonly value: number
}

export interface GamepadHapticsLike {
  playEffect?: (
    type: 'dual-rumble',
    parameters: {
      duration: number
      strongMagnitude: number
      weakMagnitude: number
    },
  ) => Promise<unknown>
  pulse?: (value: number, duration: number) => Promise<boolean>
}

export interface GamepadLike {
  readonly connected: boolean
  readonly axes: readonly number[]
  readonly buttons: readonly GamepadButtonLike[]
  readonly vibrationActuator?: GamepadHapticsLike | null
}

const GAMEPAD_DEADZONE = 0.2
// Standard-layout indices. The HUD legend has always advertised these two;
// until now nothing read them, so a pad could neither pause nor scan.
const GAMEPAD_VIEW_BUTTON = 8
const GAMEPAD_MENU_BUTTON = 9
const GAMEPAD_DASH_BUTTON = 1
interface TouchInputState {
  moveX: number
  moveZ: number
  aimX: number
  aimZ: number
  aimActive: boolean
  dashPending: boolean
}

const touchState: TouchInputState = {
  moveX: 0,
  moveZ: 0,
  aimX: 0,
  aimZ: 0,
  aimActive: false,
  dashPending: false,
}

/** Shared by the DOM touch HUD and the fixed-step input sampler. */
export const touchInput = {
  setMove(x: number, z: number): void {
    ;[touchState.moveX, touchState.moveZ] = normalizeAxes(x, z)
  },
  setAim(x: number, z: number): void {
    ;[touchState.aimX, touchState.aimZ] = normalizeAxes(x, z)
    touchState.aimActive = Math.hypot(touchState.aimX, touchState.aimZ) > 0.05
  },
  pressDash(): void {
    touchState.dashPending = true
  },
  reset(): void {
    touchState.moveX = 0
    touchState.moveZ = 0
    touchState.aimX = 0
    touchState.aimZ = 0
    touchState.aimActive = false
    touchState.dashPending = false
  },
}

function buttonPressed(gamepad: GamepadLike | null, index: number): boolean {
  const button = gamepad?.buttons[index]
  return button !== undefined && (button.pressed || button.value >= 0.55)
}

function remapAxis(value: number): number {
  const magnitude = Math.abs(value)
  if (!Number.isFinite(value) || magnitude <= GAMEPAD_DEADZONE) return 0
  const normalized = (magnitude - GAMEPAD_DEADZONE) / (1 - GAMEPAD_DEADZONE)
  return Math.sign(value) * Math.min(1, normalized)
}

function normalizeAxes(x: number, z: number): readonly [number, number] {
  const length = Math.hypot(x, z)
  return length > 1 ? [x / length, z / length] : [x, z]
}

/**
 * Browser events feed this adapter while the fixed physics step samples it.
 * Press edges survive until sampled, preventing render cadence from eating a
 * pause request. Equipped weapons acquire targets and fire themselves.
 * Every button action is edge-triggered; only movement and aim report holds.
 */
export class InputActionAdapter {
  private readonly keys = new Set<string>()
  private pendingPause = false
  private pendingDash = false
  private previousGamepadButtons = new Set<number>()
  private device: InputDevice = 'keyboard-mouse'

  keyDown(code: string, repeat = false): void {
    this.device = 'keyboard-mouse'
    this.keys.add(code)
    if (repeat) return
    if (code === 'Escape') this.pendingPause = true
    if (code === 'Space') this.pendingDash = true
  }

  keyUp(code: string): void {
    this.keys.delete(code)
  }

  pointerMoved(): void {
    this.device = 'keyboard-mouse'
  }

  reset(): void {
    this.keys.clear()
    this.pendingPause = false
    this.pendingDash = false
    this.previousGamepadButtons.clear()
  }

  sample(gamepad: GamepadLike | null): InputActionFrame {
    const connectedGamepad = gamepad?.connected ? gamepad : null
    const gamepadButtons = new Set<number>()
    for (const index of [
      GAMEPAD_DASH_BUTTON,
      GAMEPAD_VIEW_BUTTON,
      GAMEPAD_MENU_BUTTON,
    ]) {
      if (buttonPressed(connectedGamepad, index)) gamepadButtons.add(index)
    }

    const gamepadMoveX = remapAxis(connectedGamepad?.axes[0] ?? 0)
    const gamepadMoveZ = remapAxis(connectedGamepad?.axes[1] ?? 0)
    const gamepadAimX = remapAxis(connectedGamepad?.axes[2] ?? 0)
    const gamepadAimZ = remapAxis(connectedGamepad?.axes[3] ?? 0)
    const gamepadActive =
      gamepadButtons.size > 0 ||
      Math.hypot(gamepadMoveX, gamepadMoveZ) > 0 ||
      Math.hypot(gamepadAimX, gamepadAimZ) > 0
    if (gamepadActive) this.device = 'gamepad'
    const touchActive =
      Math.hypot(touchState.moveX, touchState.moveZ) > 0 ||
      touchState.aimActive ||
      touchState.dashPending
    if (touchActive) this.device = 'touch'

    const pausePressed =
      this.pendingPause ||
      (gamepadButtons.has(GAMEPAD_MENU_BUTTON) &&
        !this.previousGamepadButtons.has(GAMEPAD_MENU_BUTTON))
    const dashPressed =
      this.pendingDash ||
      touchState.dashPending ||
      (gamepadButtons.has(GAMEPAD_DASH_BUTTON) &&
        !this.previousGamepadButtons.has(GAMEPAD_DASH_BUTTON))
    const keyboardMove = normalizeAxes(
      (this.keys.has('KeyD') ? 1 : 0) - (this.keys.has('KeyA') ? 1 : 0),
      (this.keys.has('KeyS') ? 1 : 0) - (this.keys.has('KeyW') ? 1 : 0),
    )
    const gamepadMove = normalizeAxes(gamepadMoveX, gamepadMoveZ)
    const gamepadAim = normalizeAxes(gamepadAimX, gamepadAimZ)
    const useGamepadMove = Math.hypot(...gamepadMove) > 0
    const useTouchMove = Math.hypot(touchState.moveX, touchState.moveZ) > 0
    const useTouchAim = touchState.aimActive

    this.pendingPause = false
    this.pendingDash = false
    touchState.dashPending = false
    this.previousGamepadButtons = gamepadButtons

    return {
      moveX: useTouchMove
        ? touchState.moveX
        : useGamepadMove
          ? gamepadMove[0]
          : keyboardMove[0],
      moveZ: useTouchMove
        ? touchState.moveZ
        : useGamepadMove
          ? gamepadMove[1]
          : keyboardMove[1],
      aimX: useTouchAim ? touchState.aimX : gamepadAim[0],
      aimZ: useTouchAim ? touchState.aimZ : gamepadAim[1],
      aimActive: useTouchAim || Math.hypot(...gamepadAim) > 0,
      overloadPressed: false,
      dashPressed,
      pausePressed,
      tacticalScanHeld: gamepadButtons.has(GAMEPAD_VIEW_BUTTON),
      device: this.device,
      gamepad: connectedGamepad,
    }
  }
}

export function getPrimaryGamepad(
  gamepads: readonly (GamepadLike | null)[],
): GamepadLike | null {
  return gamepads.find((gamepad) => gamepad?.connected) ?? null
}

export function rumbleGamepad(
  gamepad: GamepadLike | null,
  enabled: boolean,
  intensity: number,
  durationMs: number,
): boolean {
  const actuator = gamepad?.vibrationActuator
  if (!enabled || !actuator) return false
  const magnitude = Math.max(0, Math.min(1, intensity))
  const duration = Math.max(0, Math.min(1_000, Math.round(durationMs)))
  if (actuator.playEffect) {
    void actuator
      .playEffect('dual-rumble', {
        duration,
        strongMagnitude: magnitude,
        weakMagnitude: magnitude * 0.65,
      })
      .catch(() => undefined)
    return true
  }
  if (actuator.pulse) {
    void actuator.pulse(magnitude, duration).catch(() => false)
    return true
  }
  return false
}
