import { calculateRunPayout } from './progression'
import type {
  BiomeId,
  BossArchetypeId,
  ChamberLevel,
  DailyRecord,
  DailyBuildSnapshot,
  DifficultyRank,
  MetaProgression,
} from './types'

export const DAILY_RULESET_VERSION = 'v1'
export const DAILY_FIRST_CLEAR_BONUS = 20
export const DAILY_RECORD_RETENTION_DAYS = 31

export interface DailyRunResult {
  readonly dateKey: string
  readonly difficulty: DifficultyRank
  readonly score: number
  readonly chamber: ChamberLevel
  readonly won: boolean
  readonly biomeId: BiomeId | null
  readonly bossId: BossArchetypeId | null
  readonly buildSnapshot: DailyBuildSnapshot
}

export interface DailySettlement {
  readonly meta: MetaProgression
  readonly record: DailyRecord
  readonly runPayout: number
  readonly firstClearBonus: number
  readonly totalPayout: number
}

export function isDailyDateKey(value: unknown): value is string {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false
  }
  const year = Number(value.slice(0, 4))
  const month = Number(value.slice(5, 7))
  const day = Number(value.slice(8, 10))
  const date = new Date(Date.UTC(year, month - 1, day))
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  )
}

/** Asia/Seoul has a fixed UTC+09:00 offset and no daylight-saving time. */
export function createKstDateKey(date: Date = new Date()): string {
  if (!Number.isFinite(date.getTime())) throw new RangeError('Invalid date')
  const kst = new Date(date.getTime() + 9 * 60 * 60 * 1_000)
  const year = kst.getUTCFullYear()
  const month = String(kst.getUTCMonth() + 1).padStart(2, '0')
  const day = String(kst.getUTCDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

export function createDailySeed(
  dateOrKey: Date | string = new Date(),
  version = DAILY_RULESET_VERSION,
): string {
  const dateKey =
    dateOrKey instanceof Date ? createKstDateKey(dateOrKey) : dateOrKey
  if (!isDailyDateKey(dateKey)) {
    throw new RangeError(`Invalid daily date key: ${dateKey}`)
  }
  if (!/^[a-z0-9-]+$/i.test(version)) {
    throw new RangeError('Daily ruleset version must be alphanumeric')
  }
  return `STILLSEEN-DAILY-${version}-${dateKey}`
}

export function settleDailyRecord(
  meta: MetaProgression,
  result: DailyRunResult,
): DailySettlement {
  if (!isDailyDateKey(result.dateKey)) {
    throw new RangeError(`Invalid daily date key: ${result.dateKey}`)
  }
  const previous = meta.dailyRecords.find(
    (record) =>
      record.dateKey === result.dateKey &&
      record.difficulty === result.difficulty,
  )
  const improved = previous === undefined || result.score >= previous.bestScore
  const dayRewardClaimed = meta.dailyRecords.some(
    (record) => record.dateKey === result.dateKey && record.rewardClaimed,
  )
  const firstClear = result.won && !dayRewardClaimed
  const runPayout = calculateRunPayout(result.score, result.difficulty)
  const firstClearBonus = firstClear ? DAILY_FIRST_CLEAR_BONUS : 0
  const record: DailyRecord = {
    dateKey: result.dateKey,
    difficulty: result.difficulty,
    attempts: (previous?.attempts ?? 0) + 1,
    bestScore: Math.max(previous?.bestScore ?? 0, Math.max(0, result.score)),
    bestChamber: Math.max(
      previous?.bestChamber ?? 0,
      Math.max(0, result.chamber),
    ),
    won: (previous?.won ?? false) || result.won,
    rewardClaimed: (previous?.rewardClaimed ?? false) || firstClear,
    biomeId: improved ? result.biomeId : (previous?.biomeId ?? null),
    bossId: improved ? result.bossId : (previous?.bossId ?? null),
    buildSnapshot: improved
      ? {
          loadout: { ...result.buildSnapshot.loadout },
          permanentStatLevels: { ...result.buildSnapshot.permanentStatLevels },
        }
      : (previous?.buildSnapshot ?? {
          loadout: { ...result.buildSnapshot.loadout },
          permanentStatLevels: { ...result.buildSnapshot.permanentStatLevels },
        }),
  }

  const records = [
    ...meta.dailyRecords.filter(
      (entry) =>
        entry.dateKey !== result.dateKey ||
        entry.difficulty !== result.difficulty,
    ),
    record,
  ]
  const retainedDateKeys = [...new Set(records.map((entry) => entry.dateKey))]
    .sort((a, b) => b.localeCompare(a, 'en'))
    .slice(0, DAILY_RECORD_RETENTION_DAYS)
  const retained = new Set(retainedDateKeys)
  const dailyRecords = records
    .filter((entry) => retained.has(entry.dateKey))
    .sort(
      (a, b) =>
        b.dateKey.localeCompare(a.dateKey, 'en') || a.difficulty - b.difficulty,
    )

  const totalPayout = runPayout + firstClearBonus
  return {
    record,
    runPayout,
    firstClearBonus,
    totalPayout,
    meta: {
      ...meta,
      currency: meta.currency + totalPayout,
      dailyRecords,
    },
  }
}
