/** Affixes whose payoff depends on live combat state are resolved here. */
export function resolveEliteStateStats(
  stats: EnemyStats,
  affixId: EliteAffixId | null,
  healthRatio: number,
  observed: boolean,
): EnemyStats {
  if (affixId === 'stalwart' && observed) {
    return { ...stats, armor: 0 }
  }
  if (affixId === 'frenzied' && healthRatio <= 0.3) {
    return {
      ...stats,
      attackDamage: stats.attackDamage * 1.3,
      attackCooldownMs: stats.attackCooldownMs * 0.72,
    }
  }
  return { ...stats }
}

