export const ELITE_AFFIX_IDS = Object.freeze(
  Object.keys(ELITE_AFFIX_DEFINITIONS) as EliteAffixId[],
)

export const ROOM_MUTATION_IDS = Object.freeze(
  Object.keys(ROOM_MUTATION_DEFINITIONS) as RoomMutationId[],
)

/**
 * Returns the physical/visual occluders that remain active for an encounter.
 * Keeping this decision in the domain layer ensures rendering, collision, and
 * physics-backed line-of-sight all consume the same Open Ground rule.
 */
export function getEncounterOccluders(
  occluders: readonly RoomOccluder[],
  mutationId: RoomMutationId | null,
): readonly RoomOccluder[] {
  return mutationId !== null &&
    ROOM_MUTATION_DEFINITIONS[mutationId].removesOccluders
    ? []
    : occluders
}

export function applyEliteAffix(
  stats: EnemyStats,
  affixId: EliteAffixId | null,
): EnemyStats {
  if (affixId === null) return { ...stats }
  const affix = ELITE_AFFIX_DEFINITIONS[affixId]
  return {
    ...stats,
    maxHealth: stats.maxHealth * affix.healthMultiplier,
    moveSpeed: stats.moveSpeed * affix.moveSpeedMultiplier,
    attackDamage: stats.attackDamage * affix.damageMultiplier,
    attackCooldownMs: stats.attackCooldownMs * affix.recoveryMultiplier,
    windupMs: stats.windupMs * affix.windupMultiplier,
    projectileSpeed: stats.projectileSpeed * affix.projectileSpeedMultiplier,
    armor: stats.armor + affix.armorAdd,
  }
}

export function applyRoomMutation(
  stats: EnemyStats,
  mutationId: RoomMutationId | null,
): EnemyStats {
  void mutationId
  return { ...stats }
}

/** Order is deliberately elite first, then the room-wide volatile mutation. */
export function applyEncounterModifiers(
  scaledStats: EnemyStats,
  eliteAffixId: EliteAffixId | null,
  mutationId: RoomMutationId | null,
): EnemyStats {
  return applyRoomMutation(
    applyEliteAffix(scaledStats, eliteAffixId),
    mutationId,
  )
}

export function calculateEnemyScore(
  baseScore: number,
  eliteAffixId: EliteAffixId | null,
  mutationId: RoomMutationId | null,
): number {
  if (!Number.isFinite(baseScore) || baseScore <= 0) return 0
  const eliteMultiplier =
    eliteAffixId === null
      ? 1
      : ELITE_AFFIX_DEFINITIONS[eliteAffixId].scoreMultiplier
  const mutationMultiplier =
    mutationId === null
      ? 1
      : ROOM_MUTATION_DEFINITIONS[mutationId].scoreMultiplier
  return Math.floor(baseScore * eliteMultiplier * mutationMultiplier)
}

export function getCombatantBaseScore(
  archetypeId: CombatantArchetypeId,
): number {
  return archetypeId === 'grave-warden' ||
    archetypeId === 'moonbriar-queen' ||
    archetypeId === 'parallax-seraph' ||
    archetypeId === 'null-crown'
    ? 1_000
    : 100
}

export function calculateCombatantScore(
  archetypeId: CombatantArchetypeId,
  eliteAffixId: EliteAffixId | null,
  mutationId: RoomMutationId | null,
): number {
  return calculateEnemyScore(
    getCombatantBaseScore(archetypeId),
    eliteAffixId,
    mutationId,
  )
}

export function getEliteCount(
  chamber: ChamberLevel,
  difficulty: DifficultyRank,
  routeRisk: RouteRisk,
  eligibleEnemyCount: number,
): number {
  const count =
    chamber < 4
      ? 0
      : chamber <= 5
        ? 1
        : chamber <= 8
          ? routeRisk === 'volatile'
            ? 2
            : 1
          : chamber === 9
            ? routeRisk === 'volatile'
              ? 3
              : 2
            : 0
  const cap = difficulty >= 3 ? 4 : 3
  return Math.max(0, Math.min(cap, eligibleEnemyCount, count))
}

export function getEncounterEliteCount(
  chamber: ChamberLevel,
  difficulty: DifficultyRank,
  routeRisk: RouteRisk,
  eligibleEnemyCount: number,
  mutationId: RoomMutationId | null,
): number {
  const mutationBonus =
    mutationId === null
      ? 0
      : ROOM_MUTATION_DEFINITIONS[mutationId].eliteCountBonus
  return Math.max(
    0,
    Math.min(
      difficulty >= 3 ? 4 : 3,
      eligibleEnemyCount,
      getEliteCount(chamber, difficulty, routeRisk, eligibleEnemyCount) +
        mutationBonus,
    ),
  )
}
